window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_074"]={"n":"韩雍","dyn":"明","poems":[{"t":"同年会诗分韵得呦字","f":"五言古诗","c":["忆昔甫弱冠，鹿鸣歌呦呦。","遂能从群仙，直上琼林游。","琼林探名花，少年我其尤。","同披宫锦袍，共泛黄金瓯。","一时吐壮气，浩浩横九州。","岂徒践董贾，实欲肩伊周。","朅来十五载，各有官守忧。","友情胶漆深，宦迹参商侔。","荣落虽或殊，大闲鲜遗羞。","贤科称得人，吾榜居最优。","迩闻黄门第，开筵集斯流。","尚齿不尚官，款曲偏绸缪。","尊罍叠献酢，珠玉纷赓酬。","我惭镇南邦，末席趋无由。","忽得春卿书，分韵为我留。","旦准昔同列，推荐行阴谋。","王聂始同曹，败覆终相雠。","彼皆古同年，智愚难匹俦。","作诗附终篇，相期鉴前修。","明秋我入觐，后会知能不。"]},{"t":"题行台骢马行春图","f":"五言古诗","c":["芳春日和煦，乘骢远巡游。","品类遂生育，嘉景罗道周。","青山高插天，绿水深不流。","乔松与脩竹，岁寒君子俦。","纷纷李桃花，竞艳俱含羞。","触物感时叙，方寸恒多愁。","诛锄奸宄凶，一道风霜秋。","斯乃职分常，孰较劣与优。","所贵布德化，先解黎庶忧。","于焉起沈滞，于以伸冤幽。","惠此茕独民，而且扶善柔。","所行苟皆春，厥职斯无尤。","况嗟国步艰，切齿期复雠。","勤王无路归，空横济川舟。","写图警朝夕，黾勉追前修。"]},{"t":"壬申岁暮预约同寅余公新正郊游值霖雨闷甚正月三日因携壶独酌贡院池亭怅然有怀","f":"五言古诗","c":["天眷隆浅薄，日夕不宁处。","兹焉肇新岁，崇朝积阴雨。","念此休暇期，客抱无可语。","呼童携斗酒，聊此适襟宇。","岂但解劳瘁，亦以乐治理。","高亭独危坐，八窗静如洗。","亭下方池深，举网得鲜鲤。","烹鲜浮大白，感叹不能已。","堪舆寄渺然，固知若逆旅。","君亲德未酬，徒以身自许。","所幸年未暮，勉进或有取。","谁能副我图，怅然忆知己。"]},{"t":"再用前韵奉酬同寅余公持敬","f":"五言古诗","c":["天将启中兴，神龙在渊处。","一朝飞在天，云从作霖雨。","若人素端重，殊无妄笑语。","栋梁美才具，圭璋秀姿宇。","臣邻帝左右，四海率化理。","岂但蛮夷宾，更誇甲兵洗。","羡君风云会，不殊禹门鲤。","棘寺兰台荣，超迁正未已。","用罚克明慎，体念大易旅。","丈夫幸遭际，何须羡巢许。","默默古所羞，谔谔古所取。","相勉陈嘉猷，致君日恭己。"]},{"t":"苦雨阻风夜泊剑江龙雾洲述怀十二韵三月四日也","f":"五言古诗","c":["积霖殆三旬，阴云不能扫。","深江浩无涘，滔滔走黄潦。","怒风长号鸣，排空雪山倒。","东作已逾时，耕子心悄悄。","百谷未始播，平畴尚丰草。","农事或荒废，生民曷温饱。","蹇予德浅薄，致此灾沴兆。","惕焉发深省，中怀自忧懊。","谁能补天漏，捧出日杲杲。","雨旸允时若，稼穑遂坚好。","维舟坐终夜，无计叩穹昊。","古闻诚可格，我但精意祷。"]},{"t":"寄乡先生张养正医师","f":"五言古诗","c":["君子抱道德，所志恒在民。","达则善天下，穷亦思济人。","济人伊何切，医道体至仁。","先生吴中彦，医名冠时绅。","早承家世传，群书探其真。","疗病固本元，制药分君臣。","死生一脉决，其应若有神。","沈痾一剂起，奇效时能臻。","且其不责报，尝欲先贱贫。","所以贤大夫，礼遇隆嘉宾。","宋清韩伯休，鄙哉何足论。","越人与元化，足以继后尘。","况其卓荦才，高谈妙经纶。","斯人苟出仕，所志回阳春。","伟哉张先生，医中之凤麟。","作诗寄遐想，用俟观风陈。"]},{"t":"赠别李文曜少卿","f":"五言古诗","c":["仲冬倏云暮，朔风始凄其。","寒云吹不开，冻雨连朝霏。","征夫倦行迈，暂尔停葛溪。","命驾访故人，夜方抵其庐。","故人忻我来，呼童罗酒卮。","劝酬心孔欢，痛饮何能辞。","重念贤昆季，能文复能诗。","隐显虽不同，声名皆四驰。","蹇予凉薄才，托交共襟期。","兹焉或倾倒，开我茅塞私。","我笑王子猷，雪夜访戴逵。","一棹至剡溪，云胡遽然归。","又笑严中丞，草堂访布衣。","礼遇虽或勤，中怀积町畦。","岂若吾主宾，一诚弗相疑。","友道固若是，彼徒纷纷为。","仆夫告夜阑，漏鼓声迟迟。","振衣出门去，伸谢宁无词。"]},{"t":"乡友张汝明陆宗海宗湜宗博皆良契也别久而思申友道以告之盖寓内交之义云耳","f":"五言古诗","c":["伐木诗久废，友道益以缺。","纷纷市井徒，权货日交接。","权门势方盛，炙手时可热。","一朝势或倾，掉臂随断绝。","货室利可资，相亲竞谀悦。","有时利或尽，反面肆欺蔑。","翟公曾书门，冯驩亦喻说。","斯乃理自然，古人言至切。","我尝处乡邦，所友多俊杰。","一张与三陆，门第皆阀阅。","四人与我游，情好罔优劣。","彼非因势趋，我非因利结。","有义恒相规，有过恒相讦。","胶漆意永固，芝兰味无别。","暌违甫二载，远怀不能歇。","嗟我门第衰，一弟更单孑。","西山日薄时，有力不能竭。","定省无归期，中肠自呜咽。","况乏裨益才，所至嗤政拙。","深惭立堪舆，亏此忠孝节。","所赖惟同心，旦暮一扶挈。","我爱晏平仲，交久敬不辍。","又爱朱晖贤，妻子托能惬。","作诗寄殷勤，此心誓如铁。","相勉永弗谖，期以效前哲。"]},{"t":"九江候孟诚李都不至而回留此寄情","f":"五言古诗","c":["同年复同官，别久重相忆。","闻君北堂讣，使我增恻恻。","远来致生刍，兼之慰忧戚。","山头侧身望，十日未能即。","试问东来船，杳然无踪迹。","匍匐无计往，而且乏羽翼。","况奈心事牵，匆匆逼行色。","空须怅然归，欲候那可得。","莫嗔南风狂，莫怪江水逆。","古称会面难，何时此情释。","愿言节哀痛，终图报深德。"]},{"t":"直斋古诗为乡人韦孟诚题","f":"五言古诗","c":["平生方寸间，秋毫未尝蓄。","譬之劲弓弦，力挽不能簇。","又若剡木矢，宁折不可曲。","叹彼姜公辅，售名徒取辱。","岂如史鱼贤，宣尼亦称服。","勖哉鉴诸古，不渝允终谷。"]},{"t":"挽乐佥宪妻刘孺人","f":"五言古诗","c":["古有乐羊妻，劝学尝断织。","又有姜诗配，养姑孝能力。","寥寥千载下，孺人继芳迹。","淑德馨芝兰，贞心厉金石。","相夫学成仕，秉宪克善职。","奉姑养厥志，匪但丰衣食。","况能教子姓，尤善遇宗戚。","所以贤哉名，里闾共钦式。","遂承天恩褒，紫绶映朱翟。","年方跻下寿，易箦遽永毕。","崇冈玉深埋，碑有太史笔。","观风采列传，光荣耀无极。"]},{"t":"久苦淫雨喜晴登聚奎楼有作","f":"五言古诗","c":["旬时苦淫雨，不得顽云开。","平湖涨瀰漫，矮屋垣多颓。","四郊亦茫茫，禾黍伤胚胎。","吾民失生业，田叟尤悲哀。","博施志虽勤，济众诚难哉。","惭无燮理能，获戾曷敢推。","荷此苍苍仁，幸矣回凶灾。","朝阳发光彩，飘风自南来。","长养万物成，且阜斯民财。","登楼一举手，倚栏重徘徊。"]},{"t":"登湖口上钟岩阁有感而题","f":"五言绝句","c":["爱此江阁幽，维舟坐终日。","本徒玩化理，不是荒游逸。"]},{"t":"分少陵诗句寿渔乐先生七十 其一 人字","f":"五言古诗","c":["练川有达士，德谊重搢绅。","轩冕非所图，以渔乐天真。","五湖浩烟波，扁舟一丝纶。","子陵富春山，吕望渭水滨。","遗风邈百世，于今睹斯人。","昭代访遗贤，会见迎蒲轮。"]},{"t":"分少陵诗句寿渔乐先生七十 其二 生字","f":"五言古诗","c":["春秋倏云迈，林泉寄馀生。","有子经济才，宪府蜚英声。","推封拜嘉宠，龙章下承明。","乌纱豸锦袍，白日昭光荣。","人生有斯乐，况值时治平。","仰天一大笑，举杯劝长庚。"]},{"t":"分少陵诗句寿渔乐先生七十 其三 七字","f":"五言古诗","c":["贾艺不欲售，甘心事休逸。","老陪香山九，贤如竹林七。","一朝天恩下，光辉照蓬荜。","脱却逍遥巾，从容佩簪绂。","芝兰间玉树，跄跄绕前膝。","举觞祝亲寿，愿与南山匹。"]},{"t":"分少陵诗句寿渔乐先生七十 其四 十字","f":"五言古诗","c":["桑榆景弥好，福祉自天锡。","偕老复寿康，安居享禄食。","练川乔木家，屈指百无十。","新秋时雨霁，华堂荐绅集。","金樽注流霞，饮如长鲸吸。","酒阑月初上，光芒照南极。"]},{"t":"分少陵诗句寿渔乐先生七十 其五 古字","f":"五言古诗","c":["平生厌尘俗，雅志素希古。","优游林泉下，甘与麋鹿伍。","寿考跻七旬，禄养享三釜。","佳辰集良宾，肆筵设樽俎。","翩翩青鸟来，蟠桃送王母。","弃核齐昆崙，遐龄岂胜数。"]},{"t":"分少陵诗句寿渔乐先生七十 其六 来字","f":"五言古诗","c":["新秋绂麟期，清风自天来。","烹龙且炰凤，华堂寿筵开。","有客海上至，自云出蓬莱。","喜君寿且康，为献流霞杯。","主人心孔欢，须臾玉山推。","遥遥故乡心，何当一追陪。"]},{"t":"分少陵诗句寿渔乐先生七十 其七 稀字","f":"五言古诗","c":["宿云净遥空，瑞彩腾少微。","亦有南极星，中宵烂光辉。","哲人初度晨，眉寿世所稀。","朝阳丹凤雏，翙翙翱翔归。","高堂敞华筵，珍羞击鲜肥。","岁岁祝长生，孝子心无违。"]},{"t":"送简庵王先生参政湖广","f":"五言古诗","c":["条风扇微和，冻柳青始萌。","载酒出东郭，言饯君子行。","举觞未及酬，潸然涕沾缨。","念昔侍芹泮，知遇如平生。","慇勤道愚蒙，学业幸尔成。","感此恩义重，欲报心怦怦。","同朝二十年，岂异骨肉情。","方资永承式，遽尔欢戚并。","乔迁佐雄藩，买舟趣脩程。","且展经济略，大拯疮痍氓。","坐使湖湘间，境土悉以平。","勋庸动宸极，召用谅匪轻。","斯时重盍簪，相与匡文明。","匆匆不尽意，落日催双旌。","目断滦河舟，梦绕江汉城。","衡阳雁北来，勿惜频寄声。"]},{"t":"宝善堂为姚亚卿乡人题","f":"五言律诗","c":["世德恐或坠，名堂在瑶林。","守兹万端善，何啻双南金。","克阐父祖志，允师圣贤心。","勖哉永弗渝，馀庆来骎骎。"]},{"t":"雨中招陆尚文","f":"五言古诗","c":["积雨生百感，缅怀旧朋游。","记得布衣时，曾上君家楼。","君家慈母贤，延款礼最优。","维时作霖雨，欲归苦相留。","对床且三日，讲道何尝休。","一从砚席分，屈指二十秋。","踪迹虽阔远，此心更绸缪。","怜君命犹乖，壮志良未酬。","有司选才行，才看谒宸旒。","已登青云阶，高步谅匪忧。","而我独恋恋，访问嗟无由。","请君夜话来，消我万斛愁。"]},{"t":"问林同寅季聪疾","f":"五言律诗","c":["良契久在告，单居苦无聊。","窘然坐台署，日盻趋晨朝。","得书知未能，怅然心旌摇。","宣尼且谨疾，烦君益珍调。"]},{"t":"陈缉熙修撰先陇十咏 其一 灵岩晴旭","f":"五言律诗","c":["旸谷升朝曦，灵岩发晴光。","峦峰削金碧，林木流葱苍。","延晖入琳宫，影落浮图长。","孝子葵藿心，倾向亦皇皇。"]},{"t":"陈缉熙修撰先陇十咏 其二 震泽秋蟾","f":"五言律诗","c":["巨浸不可测，群山绕其浔。","夜深上圆景，天水光相侵。","风帆照远近，沙鸟明浮沈。","彻底年年清，照见哀哀心。"]},{"t":"陈缉熙修撰先陇十咏 其三 光福烟霏","f":"五言律诗","c":["山寺延倒景，烟霏坐来深。","残红敛杰阁，浮翠迷遥林。","归鸟晻霭中，高塔亦阴阴。","瞑色欺泪眼，犹闻钟磬音。"]},{"t":"陈缉熙修撰先陇十咏 其四 穹窿云气","f":"五言律诗","c":["山川有佳气，飞飞满穹窿。","变态既靡常，间色亦匪同。","随时作霖雨，赞此化育功。","凝睇不可休，疑亲在云中。"]},{"t":"陈缉熙修撰先陇十咏 其五 天平岚翠","f":"五言律诗","c":["天平带晴岚，苍翠弥峦冈。","松筠既丛茂，泉石亦幽芳。","先正百世人，庙食山之阳。","眷言慕遗德，至孝能显扬。"]},{"t":"陈缉熙修撰先陇十咏 其六 海云茶屏","f":"五言律诗","c":["海云近佳城，佳树特连理。","英英著冬花，垒垒屏障起。","红芳冒冰雪，羞与桃李比。","元勋光旧庐，吾慕逃虚子。"]},{"t":"陈缉熙修撰先陇十咏 其七 寄心脩竹","f":"五言律诗","c":["禅林茂脩篁，翠影荫玄室。","清风入林杪，锵锵奏金石。","六逸不可招，七贤已陈迹。","感古重伤今，游魂竟何适。"]},{"t":"陈缉熙修撰先陇十咏 其八 古庙乔松","f":"五言律诗","c":["庙古松亦古，居人不知年。","直干凌碧落，深柯入黄泉。","上有白鹤巢，下曾见牛眠。","殷勤筑禁步，勿使根株连。"]},{"t":"陈缉熙修撰先陇十咏 其九 沃壤西成","f":"五言律诗","c":["平畴万顷馀，多稼垂秋成。","农人毕收穫，坐见百室盈。","比屋既足食，公家亦宽征。","孝子荐时羞，取以供粢盛。"]},{"t":"陈缉熙修撰先陇十咏 其十 伏龙晚睇","f":"五言律诗","c":["伏龙来东南，蜿蜒气凝结。","孝思卜先陇，神人指真穴。","登高伫遐瞻，暮景惨分列。","髣髴见亲容，长吁泪成血。"]},{"t":"送程佥都彦实出镇辽东","f":"五言古诗","c":["彤庭拜简命，领节安东陲。","平明出都门，冠盖如云随。","祖觞未及酣，相顾何凄其。","念子公辅器，德懋才且奇。","早年历清华，声望蔚四驰。","乔迁佐台宪，风纪资维持。","欢会曾几何，曷忍遽别离。","辽阳古重镇，付托惟君宜。","君行益慷慨，所至谅有为。","千里桑麻场，百万貔貅师。","要使耕凿遂，而且甲兵治。","天骄惮威声，塞外不敢窥。","庶分东顾忧，少荅宠眷私。","微雨路尘净，轻风杨花吹。","膏车秣马行，去去莫我迟。","临岐把衣袂，更有叮咛辞。","丈夫感知遇，图报须及时。","功成早还朝，慰我遥相思。"]},{"t":"送张起韶寺正出守保定","f":"五言古诗","c":["都门歇时雨，旭日晴光流。","之子拜嘉宠，南行典名州。","名州近京国，民物富且稠。","古称治亦难，而今简才优。","惟君瑚琏器，早岁登瀛洲。","作官三十年，直道从淹留。","再登棘寺选，不喜亦不忧。","平反著劳绩，贤声彻宸旒。","于兹付重寄，期解黎庶愁。","君行勿怠荒，庶以荅鸿休。","汉廷有循吏，通显登列侯。","丈夫幸逢时，俪美当操修。"]},{"t":"作朱中书文徵犹子字说兼励以诗","f":"五言古诗","c":["云间有华族，世德乡闾推。","隐君德弥彰，六子生绝奇。","芝兰间玉树，森森列阶墀。","头角皆崭然，奚止称白眉。","伯也干父蛊，克家礼无违。","次虽少长殊，立身率能知。","长者向文学，场屋事可期。","少焉就外傅，取友能得师。","进修不怠荒，成人理无疑。","我悉命以字，走笔摛文词。","厥字义孔深，诸子当潜思。","荀氏十龙驹，窦老五桂枝。","联芳载典籍，千古家声垂。","勉旃踵遗休，图报明盛时。"]},{"t":"寄大司马王公度","f":"五言古诗","c":["大才不易得，时艰良可忧。","所以古圣贤，治世怀远猷。","召公欲致政，周公勉相留。","二公心德同，俪美匡成周。","芳声播千古，人皆仰前修。","堂堂王司马，当代第一流。","以身徇国家，才气谁可俦。","方兹任经济，整顿多事秋。","如何在告中，遽尔得退休。","不知诸同列，亦曾勉留不。","昨简掌邦政，朝廷广询谋。","黄门御史言，称职惟君优。","上允即超拜，四方动欢讴。","兹闻勇退归，物议皆啾啾。","嗟予忝知己，痛惜不自由。","所惜为天下，匪为君身谋。","四方水旱多，贼盗方且稠。","须起出群才，同心运良筹。","渊衷必有在，士论终当收。","君其善养年，予未歌四愁。"]},{"t":"六月九日云中行台池亭偶成","f":"五言古诗","c":["卓午火云起，三边且炎蒸。","薄暮亦烦倦，池亭试閒登。","须臾山风来，襟怀爽如冰。","轻罗不可试，重衣更须增。","步还坐中堂，萧然一青灯。","因之发感叹，庶以知自惩。"]},{"t":"十二月二十有八日余与总兵官彰武伯杨公副总兵都督曹公地官郎中罗公习正旦仪于善化寺礼既毕杨具酒肴邀镇守太监王公守备中贵罗公同此小酌以为岁暮休暇之乐余浩然兴发因成五言古诗一章聊叙情曲且识余感","f":"五言古诗","c":["流光一何驶，冉冉芳岁阑。","嗟我裨益疏，幽怀弗能宽。","所幸封域内，物阜民且安。","既习嘉礼成，聊此閒游观。","内相三槐后，情意如芝兰。","总戎出关西，才器比琅玕。","谦冲副帅先，教子同登坛。","豫章先生裔，中贵及地官。","并驰英俊声，相从此盘桓。","禅窟大如斗，兀坐无严寒。","总戎邀曲生，羞膳罗杯盘。","忘形到尔汝，劝酬心孔欢。","馀酣豪气充，彼此戒素餐。","丈夫感知遇，岂惮世事难。","侧闻河套贼，西夏为骄奸。","安能建长策，奋飞擒可汗。","上报明主恩，尽此方寸丹。","局促空太息，不得生羽翰。","拂袖归行台，留题后人看。","欲问作者谁，台叟吴门韩。"]},{"t":"图韩范二公经略西夏事迹于正心堂之壁各系以诗著志也 其一","f":"五言古诗","c":["魏公真间气，出也遭时亨。","芳年掇巍科，柄用良匪轻。","谏垣累抗疏，四海蜚英声。","望重官益尊，台鼎司钧衡。","危疑决大策，宗社赖以平。","元勋固莫加，雅量孰可名。","维时孽寇贼，西夏为纵横。","帝简出群才，命公秉钺行。","公行志有在，壮气何峥嵘。","誓欲复土疆，肯效城下盟。","军容若山动，威令如雷轰。","贼闻胆已寒，下马遥相迎。","奉表愿纳贡，曷敢复战争。","山林有群盗，闻风亦忧惊。","薄伐即送降，不假血刃征。","坐令数千里，藩镇皆销兵。","岂惟边患除，公尤抚边氓。","开仓大赈恤，百万死复生。","西人感公恩，处处生祠成。","朝夕共瞻拜，如念慈母情。","天将倾西北，赖公手能擎。","人怀左衽忧，赖公终弗更。","一世扬伟迹，万古垂光荣。","题诗仰馀光，北斗天中明。"]},{"t":"图韩范二公经略西夏事迹于正心堂之壁各系以诗著志也 其二","f":"古风","c":["宋室治已久，三垂悉安生。","西贼何奸骄，卒然背初盟。","秦中既告急，朝野咸震惊。","范老独慨然，誓欲此贼平。","面受阃外寄，胸中百万兵。","跨马提宝刀，长驱莫敢撄。","侵疆始遍历，成算先已行。","大顺当要冲，贼必纷纷争。","板筑倏云具，旬日完高城。","贼闻倾国来，相讶如神明。","挥军与血战，败北僵尸横。","从兹胆已破，不敢窥咸京。","蜀羌亦归心，愿入为编氓。","公能推诚信，抚接如孤?。","营田万顷馀，劝课皆开耕。","西成富收穫，百室俱充盈。","有无时懋迁，日中通民情。","干戈既偃息，所至壶浆迎。","归来告天子，报功亦非轻。","黄阁赞大猷，事业尤忠诚。","惟公千载士，岂但人中英。","先忧与后乐，有志事竟成。","泰华擎空高，江汉彻底清。","流风播永世，忠献齐芳名。"]},{"t":"夏太常碧梧翠竹图为林同寅季聪题","f":"五言古诗","c":["孤桐何亭亭，脩竹亦袅袅。","根株起泉石，相引入云表。","乔枝润玄云，密叶摇翠葆。","所嘉清标同，非比华色好。","芳春斗妍姿，嗤彼众花草。","一时固悦目，零落苦太早。","节操岂若兹，霜风不能挠。","良材世皆惜，大匠解品藻。","栖食招鸾凰，厥美谩称道。","虞廷取制作，音韵天下少。"]},{"t":"淇园晴翠为前人题","f":"五言古诗","c":["芳莲出淤泥，红药翻雕阑。","托根既匪固，尘滓亦瀰漫。","惊风将雨来，艳丽纷凋残。","此君自幽洁，玉立淇水滩。","氛埃弗能侵，奇石与盘桓。","岂解避盛暑，惟知耐祁寒。","风雨时一过，园丁报平安。","劲节不少摧，秀色益可观。","都台有君子，雅操世所难。","太常交谊深，比德写琅玕。","流芳嗣卫武，题诗后人看。"]},{"t":"三茅观与左迁钱学士致仕陈太常宴集分韵 其一 沧字","f":"五言古诗","c":["揽衣上高轩，开轩俯遐荒。","江山界吴越，胜槩非寻常。","云起风隐隐，潮生浪沧沧。","好风入我怀，冰雪生襟裳。","眷言我同心，聊此尽一觞。","一觞未及酬，冥思热中肠。","丈夫感知遇，图报心遑遑。","岂须薄江湖，何暇思庙堂。","但使吾道行，咸能济时康。","所以乡先正，进退忧弗忘。","我希古之人，岁月悠且长。","何以誓此心，仰视白日光。"]},{"t":"三茅观与左迁钱学士致仕陈太常宴集分韵 其二 对字","f":"五言古诗","c":["三茅一何奇，门与越山对。","西湖在何许，苍茫隐其背。","绝顶多楼台，从来几兴废。","乔林掩映好，百鸟声琐碎。","我尝乘使车，踪迹穷宇内。","山川亦周览，佳丽鲜可配。","来兹集良宾，顿觉精彩倍。","子瞻方谪宦，若水已勇退。","行藏虽匪同，心志总弗昧。","芳尊叙寒暄，新咏写肝肺。","琼林粲珠玉，但觉我形秽。","去去各勉旃，流芳踵先辈。"]},{"t":"张司训乃尊松坡翁挽诗","f":"五言古诗","c":["我尝持使节，几到于越城。","驻节访隐君，知有松坡名。","松坡不嗜进，雅重月旦评。","道义施一乡，济利良匪轻。","一经授佳器，卓卓蜚英声。","登科作师儒，能使斯道行。","乃知松坡德，流衍在后生。","兹已作古人，闻之欲沾缨。","鄱湖水已落，弋溪鸟空鸣。","欲养不可回，孝子难为情。","勖哉图显扬，终可慰九京。"]},{"t":"寿赵总兵 其一","f":"五言律诗","c":["去年祝君寿，舣舟潇湘湾。","今年重祝君，遥遥望梅关。","梅关如在天，可望不可攀。","写我心中私，祝君比南山。"]},{"t":"寿赵总兵 其二","f":"五言律诗","c":["别来未旬月，梦寐怀斯人。","允为三军帅，拯此两广民。","曹彬不妄杀，羊祜心更仁。","仁者寿必遐，绵绵等庄椿。"]},{"t":"寿赵总兵 其三","f":"五言律诗","c":["夜起视河汉，将星光新新。","苍姬运中兴，崧岳生甫申。","时事亦孔艰，匡济惟良臣。","愿言宏厥施，乂此烝烝民。"]},{"t":"十二月二十有三日发梧州之浔与二三同事小酌书感","f":"五言古诗","c":["遐荒岁云徂，行役犹未休。","晨起戒舟子，理棹溯急流。","笳鼓声初喧，舳舻蔽江浮。","乱石白齿齿，激湍清浏浏。","长风饱蒲帆，薄暮方始收。","嗟我本驽钝，辞亲恒远游。","乌鸟亦有情，岂不怀故丘。","时事方孔棘，恩遇亦未酬。","眷兹弗荒宁，奔走不自由。","所幸二三友，同朝旧朋游。","且与倒一尊，解我百责忧。","重裀坐广堂，高爵等列侯。","丈夫苟有志，视此同一沤。","所贵慎明德，建功踵前修。","举杯望青天，思饮月氐头。"]},{"t":"寄王畏斋","f":"五言古诗","c":["儿从故乡来，一一问乡旧。","见说畏斋老，风神益明秀。","华岳出晴空，孤松立霜后。","诗书老不倦，日夕娱俎豆。","平生丈夫心，耿耿自天祐。","遥诵南山诗，祝我仁者寿。"]},{"t":"拙斋为冯泰题","f":"五言律诗","c":["世俗多尚巧，冯生志守拙。","巧或取机祸，拙岂见颠蹶。","先圣有嘉言，如愚且欲讷。","藏修务实践，庶以光阀阅。"]},{"t":"寄酬王同节大理","f":"五言古诗","c":["抱病厌尘事，懒通交游书。","辱我同心人，慰问何勤渠。","华札累数幅，新诗缀琼琚。","阳春曲调高，欲和惭不如。","况予久思退，犹荷频吹嘘。","感德报未能，临缄重踌躇。","踌躇念君子，友道一何笃。","同年同列情，终始高世俗。","量涵子明度，德继魏公躅。","廉公擅美誉，平恕罔冤狱。","高门未是荣，崇台岂云足。","辅世须大贤，相期秉钧轴。"]},{"t":"题行台喜雨堂","f":"五言古诗","c":["提兵靖南蛮，三载兵始收。","吾民尚凋弊，所事惟田畴。","如何耕植时，未见雨泽流。","地拆苗渐槁，比屋声啾啾。","且闻中原地，旱亦伤来牟。","中原流徙多，北敌怀奸谋。","一或岁大凶，所在生百忧。","我忝大夫后，与国同戚休。","德凉召时灾，恐惧当祷求。","圣主重民命，祀神礼先修。","诏未临海邦，气已潜通幽。","果然赐甘泽，旬日遍九州。","枯槁咸回苏，百谷定有秋。","酷暑亦净洗，炎荒凉飕飕。","圣德与天通，民亦知所由。","儿童竞鼓舞，父老齐歌讴。","小堂适苟完，欢感惟我尤。","群公携酒至，且有新诗投。","扁以喜雨名，酌以黄金瓯。","我愧不能当，题诗纪皇猷。"]},{"t":"世儒堂为俞山人","f":"五言古诗","c":["昔承俞山人，遗我参同契。","因之访南国，知是儒者裔。","华胄遥遥来，传书十馀世。","隐显虽弗同，守业不少替。","卦探伏羲画，辞讲三圣系。","践履无愧怍，著述有文艺。","手泽尚如新，遗像犹未敝。","山人益克肖，讲学了生计。","阿母守贞节，旌书表门第。","见重瀛洲仙，名堂与佳制。","贤声播三吴，庆泽衍千岁。","勖哉子若孙，箕裘谨终励。"]},{"t":"戊子十月五日与镇守太监陈公巡抚都宪陈公总兵都督冯公游端州七星岩","f":"五言古诗","c":["二气初荡摩，精华巧融结。","清浊既分判，崆峒见岩穴。","初登觉幽深，旁转更高洁。","嶙峋起玉桂，缭绕垂綵缬。","寒溜浮空明，巨石罗曲折。","逢逢击地鼓，洪响不外泄。","乃知化工神，难与俗儒说。","丹青笔虽妙，谁能写奇绝。","良辰羽书稀，聊此一怡悦。","辱我同心友，款留出佳设。","坐久毛骨寒，恍如在冰雪。","举觞劝满饮，浩歌激壮烈。","丈夫感知遇，图报心孔切。","所愧才德荒，弗能继前哲。","正谊不谋利，临事秉大节。","仰视苍苍天，此心誓如铁。"]},{"t":"挽琴川钱恒轩先生","f":"五言古诗","c":["洒洒美髯翁，玉骨冰雪姿。","养高虞山下，世利何尝思。","家储累万石，雅志惟好施。","积久报亦宏，有子昌明时。","飞腾践华要，清望海内知。","推恩锡龙章，辉光照门楣。","豸绣耀闾里，晚景心颜怡。","如何忽观化，竟尔迷所之。","生荣死亦哀，全福谁能追。","磨崖表新阡，隐德千古垂。","矧兹庙堂器，岂久淹藩篱。","宠光贲幽泉，加赠定有期。"]},{"t":"奉萱堂诗为吴县主簿李京春题","f":"楚辞体","c":["李君佐钜邑，奉萱有高堂。","名堂意云何，孝子心彷徨。","父兮不可见，母也幸寿康。","昔年故里居，思母情孔伤。","令迎就禄养，在客如在乡。","放衙晴日晡，闭户清宵长。","堂中具尊俎，阿母升方床。","锦衣率子妇，称寿在膝傍。","时新荐珍羞，家酿倾瑶觞。","承顺母颜色，欲我忧尽忘。","鹤发明翠冠，童颜照霞裳。","母心安且乐，遐算应无疆。","况君负俊才，佐邑人称良。","从兹懋声迹，远到未可量。","明镜颂光庭，鸾凤美仇香。","愿言踵先哲，显扬更流芳。"]},{"t":"朱挥使昆仲南园八咏 其一 半亩塘","f":"五言绝句","c":["先翁爱清致，凿池百步周。","彻底见泉窍，庆源时时流。"]},{"t":"朱挥使昆仲南园八咏 其二 一镜亭","f":"五言绝句","c":["池水明似鉴，结茅当水深。","波光兼月华，照见友恭心。"]},{"t":"朱挥使昆仲南园八咏 其三 钓鱼矶","f":"五言绝句","c":["香饵投清池，得鲜不须买。","还拟取巨鳌，长竿向东海。"]},{"t":"朱挥使昆仲南园八咏 其四 盟鸥石","f":"五言绝句","c":["二难总忘机，盘礴坐云骨。","白鸟知此心，浮波不肯没。"]},{"t":"朱挥使昆仲南园八咏 其五 梧桐井","f":"五言绝句","c":["寒甃荫佳木，报秋孤叶低。","殷勤为培植，将有鸣凤栖。"]},{"t":"朱挥使昆仲南园八咏 其六 芙蓉台","f":"五言绝句","c":["拒霜初著花，秋色满堤堰。","随时守清素，肯向东风怨。"]},{"t":"朱挥使昆仲南园八咏 其七 采莲舟","f":"五言绝句","c":["水花开满池，小艇自寻摘。","还截碧筒杯，斟醪劝佳客。"]},{"t":"朱挥使昆仲南园八咏 其八 栽菊径","f":"五言绝句","c":["绕篱植寒花，相对自怡悦。","岂但颜色好，爱彼守晚节。"]},{"t":"葑溪杂兴","f":"五言古诗","c":["霜重林已空，风高水愈涸。","荒园一散步，暮景觉萧索。","忽见古梅树，横斜出篱落。","揽衣看枝柯，相将绽红萼。","岁寒幸有此，气味尽可托。"]},{"t":"次韵留别徐武功先生","f":"五言古诗","c":["公昔秉钧轴，清班领斯文。","明良契鱼水，庆会乘风云。","忠诚帝简知，誉望谁不闻。","松筠挺节操，兰桂扬芳芬。","何期麟凤姿，误陷豺虎群。","一时暂尔屈，四海清名信。","人情自薄恶，世事多纷纭。","而今媢疾徒，屈指有几存。","挥毫迹已富，著书业尤勤。","钦仰悬九州，韬晦居海濆。","我惭拜嘉命，南陲统三军。","饯送有佳章，深感知己恩。","驽骀逐骥足，女萝附松根。","我欲助声光，相与流八垠。","请看周与召，同著万世勋。"]},{"t":"次韵留别陈大参宗理","f":"五言古诗","c":["久交意绸缪，远别情放宕。","风日扬轻暖，江山丽形状。","多君志绝人，名检不少丧。","制科奋登庸，衣绣侍天仗。","祥刑笔回春，按部气消瘴。","出参几名藩，在在茂声望。","教养功已成，群盗孰能抗。","惟公一去来，民俗系升降。","至今西川人，万口感君贶。","身休林树间，功勒彝鼎上。","离怀何足写，高义曷敢忘。","况辱饯送词，绝妙是宫样。","心閒学愈进，气老句弥壮。","达士冠乡评，吉人永神相。","万里遥遥心，相思隔天壤。"]},{"t":"次韵留别祝大参惟清","f":"五言古诗","c":["金门同待漏，紫塞同行春。","倏忽三十年，流光如隔晨。","君昔总边赋，与我尝相因。","筹谋鼓士气，谈笑清边尘。","我有朝天行，送别桑乾津。","桑乾水清浅，难垂任子纶。","还期钓东溟，斯得横海鳞。","君乃独勇退，风节超群伦。","金带横绯袍，还乡叙交亲。","湖山称雅志，诗酒娱閒身。","良会屡见招，义气高雷陈。","君虽乐取友，我岂能辅仁。","而今忽远违，相望如参辰。","赠我有佳制，锵然鸣韶钧。","阳春和诚难，鱼目惭混珍。"]},{"t":"善庆堂为祝大参赋","f":"五言古诗","c":["玉音褒先德，华扁侈上恩。","揭之君子堂，瞻仰无朝昏。","我闻先大夫，德善夙所敦。","积累既云厚，衍庆遗后昆。","卓哉人中英，擢第登黄门。","献纳著劳绩，进秩参名藩。","政成帝简知，封制出天阍。","荣恩不及养，此恨那可论。","羹墙见形容，水木思本源。","流泽不可忘，扁此示子孙。","子孙亦知感，孝养隆所尊。","题诗表世美，声光耀乾坤。"]},{"t":"刘佥宪廷美小洞庭十景 其一 隔凡洞","f":"五言律诗","c":["林屋洞天好，似不通人寰。","君家小石岩，亦在云水间。","红尘自南陌，乐事非东山。","辞荣休此中，世事无相关。"]},{"t":"刘佥宪廷美小洞庭十景 其二 题名石","f":"五言律诗","c":["小山石奇绝，诸老心所耽。","翰墨题姓名，视古亦何惭。","退之天封宫，子瞻仙游潭。","纱笼谨蔽护，千古留美谈。"]},{"t":"刘佥宪廷美小洞庭十景 其三 撚髭亭","f":"五言律诗","c":["閒亭恣吟情，起坐不自省。","霜髭时复撚，得句欲清警。","神游李杜坛，思入陶谢境。","家声占诗豪，谁敢更歌郢。"]},{"t":"刘佥宪廷美小洞庭十景 其四 卧竹轩","f":"五言律诗","c":["作轩当竹林，客至延入坐。","酒阑客散去，高枕竹根卧。","伯伦兴方豪，子美诗谩和。","自笑尘中人，如君有谁个。"]},{"t":"刘佥宪廷美小洞庭十景 其五 蕉雪坡","f":"五言律诗","c":["摩诘画已神，意到不拘束。","雪中芭蕉树，相应如碧玉。","惟君妙丹青，下笔绝尘俗。","林坡足挥扫，辋川图可续。"]},{"t":"刘佥宪廷美小洞庭十景 其六 鹅群沼","f":"五言律诗","c":["学书宗右军，放鹅满清沼。","观鹅得腕法，妙出人意表。","墨池洗未涸，兰亭临已了。","挥洒满世间，谁言晋书少。"]},{"t":"刘佥宪廷美小洞庭十景 其七 春香窟","f":"五言律诗","c":["花树结成幄，花时香远闻。","主翁来宴坐，百和常芬芬。","燕寝閒自凝，朝衣不须薰。","笑彼沈檀亭，豪奢何足云。"]},{"t":"刘佥宪廷美小洞庭十景 其八 岁寒窝","f":"五言律诗","c":["万卉尽凋落，桧柏犹苍苍。","爱兹岁寒操，结窝与徜徉。","直干并凌云，真心同耐霜。","堪怜梁栋材，未得登庙堂。"]},{"t":"刘佥宪廷美小洞庭十景 其九 橘子林","f":"五言律诗","c":["绕山种橘树，枝叶团阴森。","霜后熟累累，万颗垂黄金。","江陵莫专美，龙阳已成林。","摘来赠亲友，羲帖不须临。"]},{"t":"刘佥宪廷美小洞庭十景 其十 藕花洲","f":"五言律诗","c":["种藕绕芳洲，藕生绿荷长。","南风催花发，十里闻清香。","饮客折碧筒，解酲啖雪霜。","眷言君子心，千古同芬芳。"]},{"t":"桂山诗","f":"五言古诗","c":["桂山何奇哉，峰峦起平地。","星罗数百里，像物非一类。","列柱擎空高，围屏障天翠。","尖分笔格巧，棱削剑锋利。","海螺争献新，玉笋并呈瑞。","重岩垂万象，深洞容百骑。","河变梁犹存，关徙门未閟。","还多怪异状，物类无可譬。","石罅泻寒泉，清响更幽致。","丹青笔虽妙，图画良不易。","想当开辟时，清浊各奠位。","精华妙凝结，旁礴隐深粹。","洪水滔天流，壅土日消坠。","岿然不可动，参杂如布置。","儒先历览多，载籍有题识。","仙都雁荡景，角胜须在次。","始知寰中山，奇绝更无二。","所惜在荒远，世人少瞻视。","我惭本书生，承乏当阃寄。","提兵靖百越，黾勉幸成事。","性爱山水游，羁绊弗能遂。","故兹佳胜境，六载始一至。","骇目惊心神，欲去还默记。","岂徒玩物理，亦欲长仁智。","况逢休明时，德化广渐被。","九州安耕凿，四海息烽燧。","乘閒此游观，冠盖总贤使。","相与片时乐，感激知所自。","走笔题新诗，磨厓刻深字。","非追浯溪颂，聊补桂林志。"]},{"t":"知止为乡人陆仲玑题","f":"五言古诗","c":["我尝戒盛满，深恐近危辱。","因之号知庵，恒警知止足。","陆生江湖士，何苦志亦笃。","生尝从我游，我识此心曲。","世业甘自守，分外非所欲。","苟求若临渊，却步如执玉。","好礼极清致，亲贤异流俗。","保终诚德人，烦生尚加勖。"]},{"t":"成化七年秋八月自梧州出巡至平乐历诸险滩悯舟子劳甚感叹有作手书于郡学示知音者","f":"五言古诗","c":["楼船发苍梧，江水何汤汤。","清湾不时转，石滩险非常。","显伏罗虎兕，参错森剑铓。","砰轰地出雷，沸腾釜扬汤。","夹岸山壁立，涧谷缘其傍。","深陡力难为，无路兼无梁。","引缆既弗能，操桨亦有妨。","篙师极力进，群叫如发狂。","道甫逾半千，滩数百十长。","继旬始能达，疲惫已莫当。","雇直仅足食，曷有赢馀粮。","所幸得无虞，劳损不自伤。","长江有巨贾，连舟竖危樯。","开帆趁好风，破浪飞汪洋。","无烦役心力，倏至千里疆。","得售重利还，里闾誇富强。","一时或不戒，倾摧见灾殃。","乃知覆载间，人事诚眇茫。","淹速虽靡同，夷险未易量。","因之发警悟，省已益不遑。","尽瘁固所甘，幸致非所望。","循理听自然，终始永弗忘。"]},{"t":"道崇德将走谢夏大理掣肘兴阑中止 其一","f":"五言律诗","c":["别去忽五月，悠悠劳我情。","相望才咫尺，何如难合并。","推窗看明月，月落参已横。","公事未易了，怅然忆平生。"]},{"t":"道崇德将走谢夏大理掣肘兴阑中止 其二","f":"五言律诗","c":["感君极爱我，新句累百言。","一笔不苟简，兼之叙寒暄。","当宁眷老成，相将入词垣。","为草嚇蛮书，壮观颜平原。"]},{"t":"题简庵王先生折桂图","f":"古风","c":["团团明月夜漏长，森森仙桂秋风凉。","碧玉枝摇兔窟影，黄金花喷龙涎香。","广阳先生志勤苦，豪气直接清虚府。","读书养就郗诜才，成名不用吴刚斧。","青云绕足蹑丹梯，耸身平步非攀跻。","一枝月里手亲折，百人榜上名高题。","归来天香满衫袖，箫鼓欢迎绚晴昼。","故园桑梓增馀光，泮水菁莪誇独秀。","有如沧溟起鲲鹏，乘风?浪争骞腾。","扶摇万里一翅力，喧啾百鸟知谁能。","又如渥洼产骐骥，逐电排空难控制。","康庄千里一日程，龌龊驽骀甘自弃。","亨衢发轫从此通，明年挟策游南宫。","琼林深处春如海，一枝还折状元红。"]},{"t":"爱葵为姚御史鹏题","f":"七言古诗","c":["古闻御史台名兰，又闻御史台列柏。","文章御史独爱葵，岂爱葵花好颜色。","台端五月花正浓，绕阶浅白兼深红。","太阳行空转倾向，花心正与吾心同。","吾心爱君亦忠赤，欲格君心辅君德。","激扬绳纠皆为君，誓比葵花恒向日。","勖哉御史殚厥心，栽培此花永规箴。","花有枯荣性无改，莫愁花老风霜侵。"]},{"t":"题湖口下钟岩白云亭","f":"楚辞体","c":["山僧凿开白云根，因之作成白云亭。","亭中白云扫不尽，朝朝暮暮飞冥冥。","昔曾飞向金陵郭，映水摇城动高作。","又曾飞到黄鹤楼，载却仙人入寥廓。","于今亭畔云常笼，登临便觉腾云中。","天风一吹忽飘散，顷刻变化如神工。","当窗献瑞成五色，直上青霄捧红日。","出户从龙作霖雨，四海苍生被膏泽。","云兮云兮尔诚奇，见尔使我增歔欷。","未能乘尔帝乡去，又空望尔吴东飞。"]},{"t":"慰同寅余公丧子","f":"古风","c":["昔有东门吴，子死无忧情。","又有卜子夏，哭子乃丧明。","古人失子同切已，哭与无忧不相比。","千载斯文较是非，东门知命卜昧理。","君家翩翩好凤毛，一朝径赴琼楼招。","双亲哭子兄哭弟，满堂泪雨长悲号。","人生百年如梦觉，此身朝夕亦难料。","三槐五桂终尘灰，子女存亡何足道。","君方与国为栋梁，莫因无益空毁伤。","且与故人同一醉，明遣玄夫问苍苍。"]},{"t":"九鹚图为孟仪宾题","f":"古风","c":["有鸟有鸟名舂锄，霜衣雪发形清癯。","閒心只与鸥鸟伴，野趣不受樊笼拘。","恍如少府池边立，又似吴王鼓中出。","群聚应怜芳草青，孤飞点破空山碧。","国宾儒雅能得师，平生方寸无邪思。","宣尼大训寓此图，携来索我题新诗。","李杜雍陶音已绝，我欲题诗愧才劣。","但愿取彼霜衣制羽扇，一挥扫除四海苍生热。"]},{"t":"访少卿李公因送予至小箬邮亭赋此赠别","f":"七言古诗","c":["平生懒与俗士交，下视权贵如秋毫。","羡君文章冠天下，急流勇退人尤高。","联芳况有难兄在，隐德香名重当代。","林下优游日唱酬，新诗还驾苏黄派。","惭予浅薄无治功，质疑问道期相从。","却怜聚散若风絮，三载始得重相逢。","邮亭别君一杯酒，企仰高风重回首。","后夜风清月白时，君卧空山我奔走。"]},{"t":"送兰庵先生至常山临别情不能禁歌以泄之","f":"七言古诗","c":["常山山头秋月明，常山渡头秋水深。","行人欲别不忍别，两意各忍无限情。","忆在滦河折杨柳，三载相思百年久。","客中欢会能几时，何事匆匆又分手。","平生最感恩义深，年来赤胆怀君亲。","攀留无计随不去，惟有水月如吾心。","吾心如水日东注，远送行舟浙西去。","又如夜月光随人，常照行人独眠处。","行过吴门上金銮，烦报平安对素餐。","此心未遂忠孝愿，因别双泪何能乾。","明朝两棹分江浙，愁向水边看孤月。","相亲未拟情不禁，且须痛饮醉时别。"]},{"t":"胡文选葡萄为戴主事宝题","f":"古风","c":["贰师将军破西域，佳种传来满中国。","上林苑里栽更多，铨曹遗老曾亲食。","爱兹品味珍且长，朝回墨洒云烟香。","盘柯蔓衍交密叶，结实磊落垂浓光。","恍如青油帐幕攒翠羽，又如黑水晶珠贯金缕。","清宵凝露坠龙须，白昼腾霜笼马乳。","戴君得之拱璧同，求题愧我非诗翁。","解酲不羡魏文帝，奉母空怀陈侍中。"]},{"t":"六月十三日德兴道中苦热小憩林下偶成","f":"七言古诗","c":["高堂广厦六月寒，我虽逸居忧素餐。","炎风烈日道路难，我虽驱驰心始安。","却怜仆夫力已殚，流浆满背何曾乾。","马头红尘滚雕鞍，四蹄汗血尤汎澜。","使我目睹心悲酸，停车解辔聊盘桓。","九州无人服冰丸，苍生多少颜无欢。","我欲大布云阴宽，吁嗟不能生羽翰。"]},{"t":"庆备倭翁都督","f":"七言古诗","c":["伟哉将军翁继武，智勇元非众人伍。","指麾阵势风云生，笑谈兵法虹霓吐。","宝刀曾斩滇池蛟，雕弓惯射阴山虎。","出镇声华已绝伦，閒居礼度尤追古。","轻裘缓带羊都督，雅歌投壶祭征虏。","帐前列校总归心，海外诸夷谁敢侮。","斥堠久断狼烟飞，望洋不见鲸波舞。","畏威奸宄尽敛迹，向化黎元皆按堵。","圣主封功下丹诏，将军进爵垂朱组。","方今万国固悉臣，犹有四夷须镇抚。","还期明堂领节钺，坐向边陲立旗鼓。","誓使天骄不敢窥，报功定见分茅土。"]},{"t":"湖口阻风拨闷","f":"七言律诗","c":["江头日日南风恶，上下风帆总深泊。","行人欲渡未能渡，独倚蓬窗叹萧索。","寄语行人且放怀，樽中有酒还须酌。","行止从来悉在天，清閒真是浮生乐。"]},{"t":"题雪景赠陈雪轩南归","f":"古风","c":["冻云茫茫天一色，六出花飞绕天白。","山间林下无人踪，草堂独卧江南客。","客乃文范先生之贤孙，养高乐道居衡门。","闲轩扫榻曲肱卧，左图右史恒讨论。","门前大雪随风飏，严寒不入芙蓉帐。","斜拥青绫足晏然，游神已在羲皇上。","披襟起望双目开，乾坤万里无纤埃。","清光正与素心合，以雪名轩心快哉。","雪轩雪轩世事不足道，山林之下风光好。","僵卧休如袁邵公，迎宾须似王元宝。","何当归棹剡溪船，登尔高轩扫取烹茶一倾倒。"]},{"t":"刘子钟郎中嶰谷秋风竹为吴郎中题","f":"古风","c":["大夏之西，沅渝之阴，有地名嶰谷，产竹成修林。","苍厓每见绿云起，白日不受红尘侵。","七月八月风森森，翠鸾飞舞青虬吟。","瀛洲仙子振环佩，商山隐者鸣瑶琴。","行看最能远清听，入坐便可消烦襟。","比来此景不易得，宦途渴想尘生心。","吴君早年登要津，此君风节素所歆。","东平才子善挥洒，笔端造化留情深。","欲君宝此如南金，作官视此为规箴。","此君终当遇伶伦，取之共和箫韶音。"]},{"t":"送乡友李原善南还","f":"七言古诗","c":["客里思乡正惆怅，故人忽自乡山来。","入门相见惊且喜，便问何日离苏台。","来时老亲曾否见，容颜比旧谁强健。","小弟真能养志无，交游孰肯常相念。","君言亲健思我归，难弟孝养真无违。","乡闾月旦论人物，数我情好而今稀。","我闻君言泪如注，旋开书屋留君住。","悲尽欢生索酒来，与君痛饮愁君去。","可怜住此未经旬，莺花看遍皇都春。","促装南行留不得，题诗送别偏伤神。","故乡到日春应尽，高堂烦报平安信。","乡人问我情何如，梦绕江南几多恨。"]},{"t":"凯还图为总兵官彰武伯杨公题","f":"古风","c":["杨将军，不易得。","虎头燕颔脩髯黑，河目龟文神气赤。","三光五岳储精华，生与皇家为柱石。","少事世父颍国武襄公，六韬三略皆精通。","手提百斤武库戟，臂挽三石乌号弓。","有时射猎驰沙漠，千万人中显英略。","南山白额赤手擒，云里双雕应弦落。","有时策马出寨游，杀气凛凛横高秋。","健儿望风不敢敌，挥刀追斩单于头。","弱冠登庸起声望，每向行营护天仗。","艰危时复展奇谋，上谷登坛为副将。","彼敌违天常，西夏为奸骄。","将军往节度，一道人歌谣。","犬羊贪心犹未已，举国入寇平时比。","挥兵鏖战却败奔，跃马穷追数千里。","僵尸弥山血成川，尽驱驼马欣凯还。","献俘奏捷天子喜，报功遣使来穷边。","赐赉便蕃未能数，更进勋阶锡茅土。","玄冠几度加貂蝉，金印三台伏螭虎。","残敌胆破夜自惊，脱身北走无留停。","云中长驱肆劫掠，守臣安得逃天刑。","宵旰勤民深轸念，在廷元老咨询遍。","堪兹重寄惟将军，召对文华隆宠眷。","尚衣出龙锦，宝藏分南金。","大官珍羞罗，良酝清香斟。","白麻黄麻颁紫禁，将军重佩征西印。","受降城中百万家，家家喜得贤方镇。","彼敌蜂屯近边烽，僣志犹欲窥南东。","将军伏兵守要害，闻风远遁穹庐空。","塞垣不见狼烟起，从此三边甲兵洗。","圣主端无西顾忧，万里长城真可拟。","画工模写奏凯归，据鞍顾盼多风威。","山川草木动华彩，旌旗戈甲生光辉。","君不见车骑将军赵充国，金城方略平羌贼。","振旅旋师报匪轻，麒麟高阁图容色。","又不见大树将军冯公孙，大破赤眉定三秦。","中兴伟迹不可泯，南宫云台写其真。","将军勋名不在古人下，云台麟阁终须画。","此画亦须宝藏之，后人一睹千金价。"]},{"t":"夏太常竹为琴川钱允言题","f":"古风","c":["坡翁作古人，老可已陈迹。","谁言古今人，才能不相及。","伟哉太常人中英，笔端造化何其精。","传得声名满天下，世人翻视文苏轻。","琴川隐君天下士，读尽诗书不求仕。","高节清风似此君，太常写赠非无意。","家藏此君三十年，隐君虽休子能传。","传来亦有父风节，携此索我题诗篇。","袁丹阳，王子猷，为爱此君名声流。","君家父子德与此君侔，我为作诗传千秋。"]},{"t":"天顺已夘端午节赐游后山观走解有作","f":"七言古诗","c":["六龙飞天天下睹，皇度神威谁敢侮。","太平时节不忘危，每值良辰犹讲武。","五月五日时雨晴，綵云缥缈祥风轻。","万岁山前辟驰道，千骑万骑皆长鸣。","翠华南来此中驻，诏许元臣同侍卫。","嵩呼拜罢玉笋齐，马上武夫争献艺。","双双立在雕鞍行，马驰人似康庄平。","背旗手戟影不侧，肩水顶火盆无倾。","画角齐吹金鼓震，发喊声停出奇阵。","飞鎗烟过如电惊，流炮星驰若雷迅。","一人骗跃三马过，两人扶抱一马驮。","马中一老傍四少，钟南进士降群魔。","双驰上下如相翮，相参换马如相厄。","倏然抰取一人过，诸葛武侯擒孟获。","倒身腹底穿周遭，老蛟捲树翻洪涛。","折腰斜从项下过，下岩猛虎声咆哮。","有时藏身在金镫，有时控驰若骖乘。","有时倒立双足擎，有时偃仰四肢定。","群马出猎争腾骧，马驮狮豹皆人妆。","饥鹰一掣堕雕鹗，良犬才纵空豺狼。","轻便巧捷纷纭去，险状难名亦难记。","军中用此出前锋，斩将搴旗孰能禦。","平生肉眼未得观，观此盛事人人欢。","总誇一时扈从乐，更美千载遭逢难。","侍臣拜谢天颜喜，大官赐燕闻天语。","御炉香袅箫韶喧，龙驭徐行仙仗起。","侍臣步入文华南，高筵广席陈肥甘。","黄封御酒味香冽，中官谕劝皆沈酣。","君臣同游皇祖诰，与民偕乐圣王道。","我皇祖述且宪章，恩德如天孰能报。","小臣有幸逢明时，寸心感激深怀思。","谫才不作长杨赋，微诚欲献卷阿诗。"]},{"t":"送锦衣焦公子廷用还京师","f":"古风","c":["霜风初收天气寒，长江万里无波澜。","江亭执手一杯酒，送君解缆归长安。","长安迢迢望亲舍，尊翁作官美声价。","锦衣日侍凤池头，宠眷虽隆心愈下。","君承家廷训，雅有文武才。","杀取贼奴受封赏，峨冠博带何荣哉。","昨来览胜游江浙，吟尽西湖好风月。","匆匆又复趣行装，应念亲庭久违别。","丈夫有志报君亲，世人未必知之真。","他年勋名满天下，始信江湖亦有人。"]},{"t":"洞庭君山歌和赵总戎韵","f":"古风","c":["使君统师征不庭，长江万里飞扬舲。","重湖缥缈接紫冥，风帆遥度一饭经。","船头击鼓如震霆，鼋鼍蛟龙皆隐形。","君山有树高亭亭，匠石不敢加斧钉。","就中岩穴虽岭巆，隐约巨浸如一星。","湘君之祠列宫庭，灵异似若司南溟。","长鲸能容李白骑，仙槎曾说张骞乘。","东南形胜莫与比，欲通道路无五丁。","乃知元气自涵蓄，润泽何假行雨瓶。","使君雅志凌空青，睨视泰华如枕屏。","清风与明月，相招时入船窗棂。","众人昏昏君独醒，欲将丹衷荅皇扃。","腰间三尺真青萍，辟兵不用丸飞萤。","渴思整顿海宇澄，乃今长驱扫膻腥。","将星昨夜光晶荧，凯歌指日在耳听。","兹辰共泊长沙汀，万马不嘶风清泠。","知君此行不少停，直指南服宣威灵。","瞬息岭海皆清宁，相期同蹑鸾凤翎。","慎固九有如郊坰，保我皇图亿万龄。","与君相守岁寒盟，令人千秋万岁仰德馨。"]},{"t":"赵总戎见惠巨鳊酬之以诗","f":"七言古诗","c":["缩项鳊鱼味最珍，长江六月尤难得。","波涛汹涌风力劲，渔人举网空费力。","元戎统师百万行，秋毫无犯严戒饬。","庖厨空虚河伯知，故遣嘉鱼助鲜食。","我曹忝陪旌旆行，此味从来不曾识。","元戎驰赐捧玉盘，烹来大嚼深感激。","吁嗟此物成百头，真乃神灵来效职。","威声从此收南邦，蜂屯蚁聚休言贼。","草草题诗谢来意，纸短情长苦相逼。"]},{"t":"赵总戎和前作见赠再次韵奉酬","f":"七言古诗","c":["世人浅见多相忌，丈夫意气自相得。","卓哉征夷真丈夫，世人谁敢较才力。","天子临轩亲授斧，一日兵戎尽修饬。","所期代天行王诛，岂但解衣更推食。","舳舻百万长江来，走卒儿童总能识。","指挥三军陈大义，日日惟将忠义激。","三军感奋若貔虎，谁不深思效臣职。","马援须标铜柱功，晋公岂纵淮西贼。","金貂玉蝉公莫辞，丈夫从来富贵逼。"]},{"t":"望衡岳有感兼怀伯颙心友偶成鄙诗千里寄意","f":"古风","c":["我尝持节巡塞北，北岳常山瞻峻极。","我今提兵征岭南，南岳衡山见奇特。","衡山奇特在目前，三峰晓霁无岚烟。","几朵芙蓉浸空碧，一条白练飞流泉。","峻极常山今想像，彷佛危峰四千丈。","高鸟难侵绝顶飞，古松特出层云上。","常山在天北，衡山在天南。","南北相望几万里，十年走马无停骖。","客中念此愁怀起，呼酒高歌却还喜。","丈夫有志在四方，饱食閒居我深耻。","知心之友松雪翁，高怀雅量与我同。","黄堂暂屈且宽慰，扶摇万里须天风。"]},{"t":"寄伯颙通政司赵参议","f":"古风","c":["与君少同窗，仕也复同朝。","朝行一日不相见，左顾右盼心无聊。","有时往还坐书阁，夜雨灯前动春酌。","有时联辔看西山，载酒携琴恣游乐。","于今各在天一方，经年相望如参商。","君虽未起得閒适，我却任重心忧惶。","我忧惶，君閒适，且各相期慎眠食。","莺花烂熳皇都春，迟我归来与君乐无极。"]},{"t":"师次永州久雨祈晴有感赠赵征夷","f":"古风","c":["君不见贰师将军伐西域，拔刀刺山泉涌出。","又不见虞公欲与夏人战，长剑一指停西日。","乃知人有忠诚心，后土皇天相终吉。","桓桓将军赵征夷，文才武略当世稀。","昨承简命佩金印，貔貅百万生光辉。","南来次师湘口岸。","骤雨连旬江水泛。","洪涛汹涌欲渡难，泊舟虽惊总无患。","先锋卜吉将启行，骤雨不息疑群情。","将军拜天诉忠悃，云开雨歇天清明。","旌旗映山谷，鼓吹喧江滩。","将军倚楼看解缆，顺流西下无狂澜。","军中感叹称稀有，父老欢呼如一口。","两广三苗不足平，百蛮重译须奔走。","吁嗟此雨晴，其事非偶然。","皇天厌祸乱，助我解倒悬。","此雨骤于十日前，溯流难上江滩船。","此雨骤于十日后，行营水浸徒流连。","雨骤我休兵，雨晴我耀武。","天意人心总和顺，会看一鼓成功报明主。"]},{"t":"平断藤峡诗","f":"古风","c":["人言断藤峡，险峻天下少。","我视断藤峡，培塿一拳小。","蜂屯蚁聚千万家，跣足蓬头尽猺獠。","数十年来肆猖獗，三广生民苦骚扰。","五征不克势益张，处处孤城未能保。","圣皇当天赫然怒，选将提兵奉天讨。","内外群公总豪杰，百万精兵雄矫矫。","共言困守非良图，必欲长驱且深捣。","雷霆砰訇鬼神怒，几日群山尽倾倒。","百鍊钢刀破新竹，万里长风振枯槁。","岩居穴处皆荡焚，瘴雾蛮烟都汛扫。","积尸如山血如川，诛夷只许留襁褓。","兔窜狐奔网罗密，我军追戮如芟草。","大藤根株悉已断，五岭封疆真再造。","振旅班师归柳营，黄童白叟迎遮道。","自言固望来苏久，不图便见成功早。","从今水陆是通衢，来去行人免迂绕。","有田可耕山可樵，共享承平永安好。","圣皇睿算天助顺，群公整顿南荒了。","丰功伟绩万古传，附骥成名愧台老。"]},{"t":"送少司徒薛公还京师","f":"七言古诗","c":["海珠寺前一杯酒，送君奏凯还京师。","君还京师我独留，执手不忍遽别离。","与君一载同相处，君总刍粮我军旅。","同心戮力功已成，共羡君才世无比。","积粮如山帛如丘，千金重赏先伐谋。","人言不殊萧相国，我道更胜张留侯。","平生节操清如许，秋月冰壶真可拟。","萧索行囊薏苡空，惟有图书为伴侣。","海风飘飘瘴雨收，乘潮解缆不可留。","扬扬意气长啸去，道傍人羡如仙舟。","高秋入见天颜喜，太常尽把奇勋纪。","三台八座定无疑，从此皇恩常眷倚。","丈夫报国思致身，江湖庙堂同此心。","君去我留不须论，要取芳名冠古今。"]},{"t":"送主事谢芳","f":"七言古诗","c":["戍边蕃将远移家，劳君将命来天涯。","天涯瘴疠人共恶，君来不见兴咨嗟。","君才落落人中杰，不学时人附炎热。","作官自是有贤名，奉使尤能守清节。","匆匆聚首便趣装，画船挝鼓辞五羊。","滇阳峡里夜可渡，红梅关上秋空防。","太平气象君都见，莫似常年浪兢战。","且须游览锦衣乡，还应归奏金銮殿。","殿头元老多故人，相见为我道情真。","谫才不堪胜重寄，只愿归老江湖滨。"]},{"t":"赠赵征夷凯还京师","f":"七言古诗","c":["桓桓将军赵征夷，人中豪杰军中师。","一朝拜命佩金印，提兵百万来边陲。","边陲蛮夷流毒久，保险为巢争死守。","将军奋甲独先登，百万雄兵谁敢后。","阵前号令雷风奔，日色昼暝天为昏。","马蹄溅乾荔江水，剑锋斫断藤山根。","兔窜狐奔弥百越，网罗处处无疏缺。","坐看群丑尽成灰，万里妖氛一时灭。","将军振旅归柳营，黄童白叟皆欢迎。","自言生长乱离久，不图便见时承平。","人言将军有神力，杀气棱棱厌群贼。","贼中遥望畏如神，狄青铜面何须饰。","藤山磨厓纪厥功，贼党不敢窥其中。","从兹两广正疆界，马援铜柱翻成空。","将军伟烈超今古，马援狄青何足数。","圣主才无南顾忧，锡封定见分茅土。","赞军台老不知兵，却喜心同见功成。","题诗送君凯还去，天涯万里难为情。"]},{"t":"成化三年春予驻师梧江之浒截竹为杙以障土阶未几竹复生者三十有三本枝叶茂密森森可爱从事诸君为予作亭题曰瑞竹予因作诗纪之","f":"古风","c":["此君之性难移植，移植从来皆有术。","子美曾言腊月栽，廷坚亦说须辰日。","醉迷之日移更嘉，非时鲜得抽萌芽。","如何斧斤斫断插江浒，又见枝叶生枯槎。","化工生物非无为，异物非妖即为瑞。","此君素有君子操，草木之妖难比类。","天兵煌煌南越平，边民垂死皆更生。","江湖必有弃置君子起，相与戮力匡文明。","坤轴气尽回，天心真厌乱。","生贤济民兆已彰，不信百蛮犹敢叛。","君不见广陵芍药金带围，世无此种人称希。","嘉祐诸贤应兆起，太平勋业流光辉。","作诗示我同心人，世间有事皆可为。","鞠躬尽瘁荅明主，勿俾前贤专美于当时。"]},{"t":"中秋文会为朱挥使昆仲题","f":"七言古诗","c":["天风吹开万里云，一轮华月秋平分。","朱家昆仲设尊俎，满堂宾客皆斯文。","斯文济济多才杰，握手登堂先看月。","高捲珠帘问月明，何不常圆有时缺。","盈虚消长理自然，月虽不言心已传。","且将美酒劝宾客，请客为我题诗篇。","须臾酒酣兴如渴，长篇短篇任批抺。","还疑风月写不尽，遍谒儒绅请题跋。","南楼老子兴亦浓，却恨年年在客中。","行将归老葑溪上，与尔中秋文会同。"]},{"t":"梁御史二亲双寿诗","f":"古风","c":["广平太守人中豪，芳年发轫由地曹。","功成名遂身早退，清风凛凛何其高。","厥配宜人善为母，雍肃齐家化乡土。","偕老东平昼锦堂，过古希年才四五。","黄金作带横绯袍，明珠裂冠攒翠毛。","双双鹤发对晚景，共誇曾荷鸾书褒。","膝前令子庙廊器，豸绣为衣频奉使。","剩有清名荣及亲，便道还乡慰亲志。","玉缸春酒葡萄香，驼峰凤髓华筵张。","绣綵当筵共称寿，泰山晔晔共辉光。","望泰山，祝亲寿，推恩指日定加封，寿与泰山同永久。"]},{"t":"与冯宪副朱挥使昆仲游东禅","f":"古风","c":["幽怀不能遣，与客游东禅。","东禅景何如，缭绕水竹笼云烟。","东堂长老号玉田，精彩矍铄神气全。","匆闻门外车马声，倒屣迎我忻忻然。","自言门巷好杉树，亲手栽植今参天。","登堂坐我蒲团上，妙香香茗时时传。","唤来高徒聪上人，颐指气使勤周旋。","须臾开筵列尊俎，款留甚觉心诚虔。","英豪宪副天下士，老成挥使人中贤。","更誇玉雪美公子，好诗好礼今无前。","携得仙家施小童，长歌大雅声清圆。","玉田欢感呼行者，青天歌舞齐联翩。","一派仙音众侧耳，重斟美酒烹肥鲜。","案头石砚压锦笺，墨浆如膏笔如椽。","诸僧罗拜不肯起，阑门索我留诗篇。","君不见远公结社住白莲，一招靖节贤名传。","又不见昌黎有书遗大颠，美誉烜赫垂千年。","愧我无能继古作，爱此光景徒流连。","草草留题拂衣去，何须更问三生缘。"]},{"t":"访沈南斋东禅无闻上人方丈有作","f":"古风","c":["昨曾访东禅，东禅方丈居西偏。","群僧琐琐不足数，但觉玉田和尚贤。","今晨复访东方丈，无闻长老尤高尚。","三寸庞眉映雪颠，纯诚实有真僧相。","人言无闻世少双，一生戒行如冰霜。","沾泥柳絮吹不动，春风上下空颠狂。","南斋诗伯常来住，好诗好画留无数。","促我题诗警众僧，众僧酣卧知何处。"]},{"t":"橘杏双清为儒医傅泽民题","f":"古风","c":["莫言苏耽神，漫说董奉仙。","惟我葑溪南，国医世称贤。","以医名世三十载，轩岐道术何精专。","开阖阴阳指间妙，斡旋造化心中玄。","回生起死已万千，何须橘叶吞清泉。","家有恒产皆良田，曾输万石周荒年。","天恩煌煌赐冠冕，杏林换谷名空传。","琴川高士感德偏，买橘买杏栽庭前。","绵州太守作佳画，刑曹司务题长篇。","想当雨过碎锦钱，结实宛如红蜡圆。","寒霜作威叶不变，黄金万颗累累然。","此时此景清且美，相对不觉尘烦蠲。","开芳樽，列绮筵，旋烹肥，时摘鲜。","东邻西舍三五友，日常醉倒林中眠。","何时使我参其间，我将世事祈苍天。","疲癃残疾谁能痊，鳏寡孤独尤堪怜。","苏董于今果未死，招起授我神方全。","我将以之游八埏，广济夭阏并颠连。"]},{"t":"忆秋谷柬其高徒陈绍祯","f":"七言古诗","c":["昔游中吴第一山，主山都纪张秋谷。","开门迎我车骑进，扫榻坐我林间屋。","我观秋谷心休休，仙风道骨非凡流。","出岫孤云袅晴昼，倚天长剑凌清秋。","笑怀顿觉高怀放，瀹茗焚香与酬唱。","时出瑶琴弹古音，旋开碧瓮浮春酿。","酒阑便与秋谷辞，弟子罗拜皆仙姿。","就中独见陈绍祯，风骨彷佛同其师。","别来十载今重访，秋谷仙踪已长往。","苍松老桂尚依然，抚景令人动遐想。","乘鸾乘鲤未可知，蜕形想似陈希夷。","还须夜夜望云表，恐有化鹤归来时。"]},{"t":"仙舟诗为郭汝祯赋","f":"七言古诗","c":["郭君之舟新且美，乍入真如洞房里。","爱君兄弟义气多，与君同泛吴淞水。","外台豸绣名四方，南邻金玉誇同乡。","我弟亦是锦衣客，开樽满座生辉光。","腊雪初晴风力壮，远山近山如玉障。","寒极翻疑酒力微，情欢不觉诗怀放。","红炉再拥银烛烧，劝酬已到夜寂寥。","东君犹自不满意，密戒舟子徐徐摇。","吴淞万顷孤舟漾，橹声摇月吴歌唱。","彷佛陶朱入五湖，依稀博望来天上。","喧阗鼓吹归渡头，傍人叹羡如仙游。","烦君勉效郭林宗，我名此舟为仙舟。"]},{"t":"送张佥宪永锡三考满入京","f":"七言古诗","c":["我昔提兵征百蛮，劳君策马来从事。","愧我虽无裴度才，爱君实有昌黎智。","献谋献策资戎机，颐指诸将谁能违。","须臾成功报天子，捷书露布皆君挥。","君才落落人争羡，况是临戎曾督战。","恩赏虽加秩未升，恨我东归未能荐。","我重拜命来天南，为君满去聊停骖。","一军相顾皆叹惜，广人恋德情何堪。","我闻无数攀留意，已具民情诉天使。","天使封章达圣聪，庙堂虚位应专俟。","苍苍之天不负人，从来久屈多大伸。","梅关尊酒且别去，相期联步趋严宸。"]},{"t":"春江会别诗","f":"古风","c":["相会才几时，相违又明旦。","如何骨肉情，恒有离别叹。","昔佐兵曹曾左迁，道出齐鲁心悬悬。","紫薇堂中驿骑发，鲁桥追送皆潸然。","当时起拜南征命，亦闻转佐湖藩政。","百万王师劳指麾，间阔多年已衰病。","归来庐下心正哀，谁知恩诏从天来。","越南万里总巡镇，兼权自愧非全才。","杨柳初青梅始白，旋整旗旄行计迫。","恰遇朝天骑从还，联舟共作江南客。","剪烛听夜雨，推篷看春山。","宦途聚散三十载，无如此会多欢颜。","舟人忽报明朝别，帆指西南分楚越。","万顷鄱湖不共游，虚负清风与明月。","明宵风月各一方，我怀恩义心茫茫。","且须今日尽杯酒，壮心莫为离情伤。","此心从来金石比，附势趋炎所深耻。","暗里前程听自然，举世相知能有几。","方今士论亦已公，圣主侧席思英雄。","云霄有日重相会，图报务欲输精忠。"]},{"t":"同年王参议孟育从事军中久矣今升左参政予与总镇两广太监陈公总兵官平江伯陈公重其为人而惜其去载酒饯行诗以华之","f":"七言古诗","c":["壬戌之春金榜开，百五十人同日喜。","三十年来渐凋谢，落落晨星不多矣。","怜君素有冰蘖操，作官久淹甘自已。","方今用贤尚恬退，忽报乔迁向南鄙。","我闻滇南古夷地，皇明抚有非昔比。","君能治理如中州，风俗应须变淳美。","瘴烟初消天日明，碧水丹山照金紫。","青油幕下行装发，囊箧萧条只图史。","府僚诸老尚含情，况我情怀曷能止。","江亭一杯聊叙别，浩浩长风布帆起。","到时若上五华山，东望传书慰知己。"]},{"t":"庆南京大理寺卿夏公季爵致仕诗","f":"古风","c":["与君同年最交契，羡君才识超当世。","喜君辞老得还乡，东望吴山促归计。","想当正统壬戌春，礼闱一见即相亲。","廷对作官有先后，感君教益非常伦。","君才相是文章伯，游艺词林声烜赫。","洒翰真追王右军，作诗不让陶彭泽。","两京棘寺当劳烦，尽心谳狱人无冤。","戴胄忠清允执法，有功仁恕多平反。","昨来奉敕巡江右，使节勤劳声绩茂。","贪吏都除政一新，疲民尽起欢如旧。","功成名遂思故乡，明廷拜谒陈封章。","圣主怜君美风节，赐君致仕归钱塘。","钱塘风景甲天下，君归游乐增光价。","捲幔观潮镇海秋，扣舷歌月西湖夜。","我尝游宦历览频，乡园况与湖山邻。","乞归未遂怀我友，不觉清泪沾衣巾。","君不闻造物由来忌美名，大名久居良亦难。","所以越大夫，扁舟五湖终不还。","所以裴晋公，诗酒昼夜穷相欢。","体天之道戒盈满，浮名与我何相干。","烦君先报湖山知，迟我归去同盘桓。"]},{"t":"赠锦衣镇抚林君以善诗","f":"七言古诗","c":["人言林君写生巧，我言林君词翰好。","名闻夷夏三十年，笔落人间比珍宝。","胸中造物如鬼神，群飞一扫皆逼真。","景随意到千万态，黄筌崔白安能伦。","兴来走笔题佳句，三峡倒倾留不住。","电光烁爚蛟龙飞，贾岛张颠见犹惧。","锦衣日侍蓬莱宫，累朝宠遇谁能同。","大烹肥羊良酝酒，日日醉饱春风中。","却想家林别多载，归梦时时飞岭海。","圣主恩怜许暂还，粤南山水增光彩。","昨来相会五羊城，庞眉皓首神气清。","盘空老鹤出尘表，想应有诀修长生。","古来一艺能名世，况君众善兼多艺。","高名准拟流千年，遐算还看过百岁。","君将赴召趋神京，预作歌诗送君行。","五云缥缈一回首，孤臣万里难为情。"]},{"t":"送宗器张方伯之浙江兼柬崇善刘方伯年况意见乎词","f":"七言古诗","c":["瘴云初收残雨歇，张君别我游江浙。","平生壮志轻别离，为惜君才心郁结。","君昔作官守四明，我来浙省闻君名。","紫薇堂上一相见，识君真是人中英。","踰时我拜南征命，君亦来参广藩政。","师行日费藉君多，我得迅扫蛮烟净。","广人被泽方歌讴，浙人望治思未休。","一视同仁徇民愿，进官移地君知不。","君才本是庙堂具，历试想应图倚注。","海内犹多事可为，好竭精忠荅知遇。","同寅方伯我同年，十载不见心茫然。","丈夫志定会有合，相期话旧五云边。"]},{"t":"庆朱良德寿五十","f":"古风","c":["去岁我当知命年，朱君寄我庆寿篇。","今年朱君庆知命，越南万里心惓惓。","岂无一尊酒，可以奉寿筵。","暮云春树空入望，无由缩地凭书传。","想当新正甫踰旬，祥光瑞气腾吴天。","元宵尚隔三四日，君家堂上灯先悬。","倾城人喜初度好，车马杂沓来群仙。","簪缨跄跄总名宦，韦布楚楚多英贤。","盖世文章列大轴，惊人诗句堆华笺。","朱君见此深感悦，难兄友爱尤忻然。","自言我尝逢此日，我弟执礼心诚虔。","今辰景好客又好，款留敢惜囊中钱。","大开天光云影亭，长筵广席罗芳鲜。","主翁劝客客酬主，洞庭春酒来如泉。","谩爇沈檀引飞鹤，高烧绛蜡催鸣弦。","歌悠扬，舞蹁跹，藏阄筹莫算，分韵诗重联。","捲帘笑看狐南星，似觉瑞彩光于前。","寿徵已见心益喜，不惜醉倒先欹眠。","夜深酒阑客散归，又报有客来相连。","送迎款洽累数日，里闾谁不称君贤。","玉雪子，贤比肩，爱尔同气心不偏，友恭之义能两全。","高风应使薄俗化，芳誉嬴得儒绅怜。","安得天下同此风，坐看民俗如古先。","老我平生半游宦，每逢初度心悽然。","何当归老葑溪头，与尔此日相周旋。","况尔昆仲寿绵延，方升之日方至川。","西岭千秋不改色，蓝田百世常生烟。"]},{"t":"壬辰岁午日与林锦衣饮于行台喜雨堂林乘兴为予挥扇面怅然有感书此赠之","f":"七言古诗","c":["忆在先朝逢午日，万岁山前常扈跸。","綵丝锦囊赐新扇，写生都是林良笔。","鼎湖龙游倏九年，林君与我各一天。","喜雨堂中忽聚首，又逢午节皆泫然。","旧恩未报新恩叠，万里炎荒恋丹阙。","须臾酒酣豪兴起，为我挥毫扫明月。","吁嗟林君画入神，一笔真可当千金。","惟我得多永珍袭，君恩友谊千年心。"]},{"t":"五月十六日与林锦衣食荔支偶成","f":"七言古诗","c":["海邦荔支品多美，绝美无如进奉子。","南人惯识已誇羡，北人初见尤惊喜。","剥开鸡卵玉满苞，嚼出琼浆香溅齿。","解酲消渴日千颗，未许杨梅雪梨比。","忆昔永元天宝间，贡出西川与交趾。","十里五里一置堠，人马困顿多道死。","此果得名想此时，讽谏有诗载青史。","我朝列圣鉴往事，穷荒献味皆禁止。","大庖九鼎罗八珍，果核时新亦无此。","我曹何幸得饱啖，念所从来感恩耳。","作诗写赠知心人，无奈心驰天万里。"]},{"t":"送夏官郎中叶廷茂还京","f":"七言古诗","c":["叶君风仪何楚楚，早岁登科入枢府。","沧海明珠天下珍，丹山彩凤人争睹。","才高绩最登大夫，职方万里时披图。","九伐简书劳钜笔，军国重事资嘉谟。","昨承简命来南国，选送降胡助诛贼。","梁公云起促归心，张翰风高急行色。","锦衣过乡天已霜，黄柑紫蟹荐寿觞。","受封双亲足怡悦，九峰山色增辉光。","却忆匡南曾聚首，共泛鄱湖醉春酒。","瞬息流光十八年，君处清华我奔走。","苍梧重会又别离，把酒话旧情难为。","庙廊虚位正相待，好展经济匡明时。"]},{"t":"送平江陈总兵","f":"古风","c":["伟哉伟哉陈将军，少年学武兼学文。","养成大才袭封爵，一出便见超同群。","登坛小试万人师，克效勤劳守廉介。","简在宸衷任愈隆，开府苍梧膺大拜。","来临百粤气益充，号令所至皆成功。","蛮夷畏威不敢起，始知世有真英雄。","迩闻漕运法多弊，况复河乾盘剥费。","积债年年无计偿，贫军狼狈空吁气。","群情却忆令祖翁，当时开创河运通。","将军家法必有得，远期步武收功同。","廷臣闻此交章荐，仰荷圣聪专倚眷。","才看徵诏下岭南，已动欢声满淮甸。","人情望公大有为，公行到日先何施。","扫除旧习正在已，讲求良法须从宜。","楼船遥遥泛秋水，明月流光照行李。","道傍拥送千万人，谁不沾巾重称美。","锦衣玉节过南京，旋除宿草拜先茔。","茔前有祠泣且告，誓图克肖延家声。","君不见萧何关中给馈饷，元功位次先诸将。","又不见寇恂河内转运足，丹青画像云台上。","丈夫富贵何足言，要使中外慕风望。"]},{"t":"题家藏夏仲昭竹","f":"七言古诗","c":["我昔乘骢按江右，仲昭来作筠阳守。","当时写竹独擅名，自昔非人不轻授。","一朝趋拜容台命，南浦楼前适相觏。","赠我朝阳舞凤图，疑似箫韶九成奏。","家藏倏忽廿四载，素绢虽陈墨如旧。","兹晨拂拭悬素壁，烂熳辉光动晴昼。","千仞翔来览德辉，九苞振起铺文绣。","须臾飒飒起风雨，又似虞廷弄清味。","光价真追老可踪，声华岂在坡翁后。","公又已为泉下客，白璧黄金亦难购。","老我题诗遗子孙，睹物思人泪沾袖。"]},{"t":"成化七年冬户部主事李君士美奉玺书清财赋于两广廉而有为严而不苛贤声闻于朝即有员外郎之擢君感激益励凡两广二十郡之地冒暑雨冲瘴毒早夜兼程遍历无遗所至人不敢干以私而搜剔奸蠹无能隐蔽绳之以法仓庾肃清亦未尝执己见以及非辜诚才德兼优之君子可重也于其归赋诗送之兼致予意","f":"七言古诗","c":["岭海穷冬变风色，瘴烟灭尽梅花白。","行台日长羽书简，载酒远送朝天客。","客乃金曹粉署郎，早登科甲随班行。","作官今已八九载，共誇节操非寻常。","昨捧天书下南越，两度岁华犹未歇。","马蹄踏遍瘴乡云，所至无人敢私谒。","千仓万箱总较量，寸丝尺缕无遗忘。","两藩财赋清似水，英声先已蜚岩廊。","圣明因此知才器，特进一官员外置。","远大从今未可量，好与皇家图济利。","国朝财赋取最宽，可堪水溢兼旱乾。","东南已嗟民力竭，西北更苦供输难。","司徒年来亦难处，左区右画劳心绪。","君还有策莫惮言，报国须当以身许。"]},{"t":"寿大司寇杨公二首 其一","f":"五言律诗","c":["身荷三朝宠，官联八座荣。","提兵不妄杀，谳狱只求生。","龟鹤应无算，熊罴定有徵。","宾筵多祝颂，谁似故人情。"]},{"t":"寿大司寇杨公二首 其二","f":"五言律诗","c":["当代推人物，惟公独占魁。","清才多裨益，阴德久栽培。","应得明珠晚，何妨白发催。","佳辰隔千里，无计劝霞杯。"]},{"t":"送吴布政致政还毗陵","f":"五言律诗","c":["盛满心知足，归休志已伸。","乐天陪九老，莱子慰双亲。","风月开三径，山林见几人。","西江有棠树，千载忆斯民。"]},{"t":"夜访李少卿回至莲塘寺同宿次少陵韵二首 其一","f":"五言律诗","c":["官道千山迥，禅宫一径幽。","故人远相送，邀我试同游。","野烧随明灭，空云任去留。","老僧惟面壁，不解利名愁。"]},{"t":"夜访李少卿回至莲塘寺同宿次少陵韵二首 其二","f":"五言律诗","c":["招提薄暮至，夹道树重重。","枝缀青猿果，巢深白鹤松。","因闻禅语秘，顿使宦情慵。","清绝题诗处，山寒雪满峰。"]},{"t":"题齐氏族谱","f":"五言律诗","c":["营丘宗法废，今喜子孙贤。","世系千年定，亲疏一本传。","载歌頍弁句，不诵角弓篇。","珍重藏诗谱，家声继郑玄。"]},{"t":"赠李伯颙下第","f":"五言律诗","c":["穷达皆由命，愁颜且暂开。","君宜登此选，天欲老其才。","旧学还加勉，初心慎莫灰。","东风云路阔，还拟占春魁。"]},{"t":"挽成规御史","f":"五言律诗","c":["投簪拂袖还，清望重于山。","举世有公论，知君无厚颜。","高风今寂寞，流水自潺湲。","千载看青史，台臣第一班。"]},{"t":"偶成","f":"五言律诗","c":["二旬登上第，十载位都堂。","遭遇古来少，感恩何日忘。","不须论毁誉，焉用卜行藏。","誓竭驽骀力，终身报圣皇。"]},{"t":"酬德诗谢乡友徐文辉以仆书童见遗","f":"五言律诗","c":["与君交十载，德义重雷陈。","分取文房仆，相资客路人。","随车春护节，扫榻夜铺茵。","愧乏琼瑶报，题诗播缙绅。"]},{"t":"山行即事有感二首寄李九川 其一","f":"五言律诗","c":["远涉登登路，愁冲活活泥。","云遮山脊断，雨助水声凄。","村火青烟湿，林花翠雾迷。","谁怜宦游客，骢马不停蹄。"]},{"t":"山行即事有感二首寄李九川 其二","f":"五言律诗","c":["草暗原头路，花粘屐齿泥。","农家一村聚，牧笛数声凄。","旅馆时时盻，乡山望望迷。","东林有归客，怪底厌轮蹄。"]},{"t":"山家","f":"五言律诗","c":["级级山田畔，农家住不移。","增茆苫破屋，编竹补残篱。","日煖开蚕早，云深放犊迟。","年年了租税，免得吏人欺。"]},{"t":"寄梅贡士鼎","f":"五言律诗","c":["青春人共誇，文彩玉无瑕。","笔扫龙蛇阵，胸蟠锦绣车。","月宫曾折桂，杏苑拟探花。","迟尔云霄上，同心佐帝家。"]},{"t":"寄陆尚文","f":"五言律诗","c":["东郭一尊酒，西江千里程。","故人不可即，孤客若为情。","秋近天风厚，时来羽翮轻。","扶摇九万里，洗耳听蜚声。"]},{"t":"寄秦以忠","f":"五言律诗","c":["宿别城东寺，参商岁月长。","天涯怀故旧，客况最凄凉。","大器晚方就，寸阴今正忙。","西风动寥廓，期尔快翱翔。"]},{"t":"宿戈阳山家将明怅然兼忆李少卿二首 其一","f":"五言律诗","c":["远路倦行迈，山家宿渐明。","催衣勤漏鼓，聒枕乱鸡声。","树杪摇风向，檐头溜雨鸣。","故乡在何处，展转不胜情。"]},{"t":"宿戈阳山家将明怅然兼忆李少卿二首 其二","f":"五言律诗","c":["达人林下卧，春梦最分明。","不设重门险，何须击柝声。","曲肱如尺稳，鼾鼻似雷鸣。","任尔朝慵起，都无尘世情。"]},{"t":"寄张维本阴阳官兼管医学","f":"五言律诗","c":["残雪江村晓，维舟曾访君。","颜华嗟久别，消息喜相闻。","步野寻春药，登台望夜氛。","此中有真乐，应笑独纷纷。"]},{"t":"寿蕳庵王先生","f":"五言律诗","c":["中年增一算，八月庆初辰。","黄鹤山头日，紫薇堂上人。","恩添江水远，香发桂枝新。","无限殷勤祝，楚天南望频。"]},{"t":"项荩臣宪副曾与予同除广东兹闻擢陕西宪使寄诗为贺","f":"五言律诗","c":["同捧外台檄，怜君独滞留。","清才不可掩，高位岂须求。","马度函关晓，云开华岳秋。","相期守初志，联步凤池头。"]},{"t":"疮疾在告蒙恩命医调治既痊入谢赋诗志感","f":"五言律诗","c":["移病闭闲门，矜怜感至尊。","上医调善药，衰疾去深根。","蒲柳重荣日，乾坤再造恩。","时平无可报，空有赤心存。"]},{"t":"题邵真人画赠唐廷璋","f":"五言律诗","c":["仙子写山川，风标自入玄。","草堂芳树里，萧寺碧云边。","钓叟方移棹，行人未息肩。","平生出尘想，对此一凄然。"]},{"t":"辛巳四月自大同宣府还朝议政五月八日陛辞还镇蒙恩赐酒饭赐钞千贯且命中官谕旨慰勉赋此志感","f":"五言律诗","c":["付托惭无效，趋朝不自安。","恐干天宪重，翻拜圣恩宽。","楮币来中使，琼筵出大官。","重还何以报，惟有一心丹。"]},{"t":"过居庸","f":"五言律诗","c":["居庸天下险，山势入青苍。","路转羊肠曲，溪分雁尾长。","关门严虎豹，烽堠禦豺狼。","愿保藩屏固，皇图万世昌。"]},{"t":"寄袁州莫别驾伯颙","f":"五言律诗","c":["鸟外云初净，宜阳望眼舒。","故人久相别，佐郡近何如。","分驾春行部，休衙夜诵书。","仰山遗庙在，希古莫踌躇。"]},{"t":"山翁","f":"五言律诗","c":["屋枕楚山麓，门临湘水滨。","树深啼鸟乱，网便得鱼新。","尘世无他虑，閒居老此身。","悠悠倦行客，转盻慕斯人。"]},{"t":"为赵总兵题扇","f":"五言律诗","c":["握柄炎荒外，三军听指麾。","良筹先已定，多算出还奇。","瘴雾随时扫，清风到处吹。","题诗比勋德，无沗赵征夷。"]},{"t":"示彭节归任","f":"五言律诗","c":["辟尔远从征，贤劳重有声。","马前朝草檄，幕下夜谈兵。","奏凯还乡去，迎亲宰驿行。","中原若开府，徵用更非轻。"]},{"t":"题三洲岩","f":"五言律诗","c":["开辟分元气，陶镕属化工。","一拳平地上，万象太虚中。","感古思羊祐，脩真慕葛洪。","登临动高兴，长啸海天空。"]},{"t":"送鸿胪寺邓主簿送安南使臣事竣还京师","f":"五言律诗","c":["相逢遽相别，归计忆神京。","百粤风尘净，孤舟日夜行。","远人空恋德，老我不胜情。","道出吴门下，烦君一寄声。"]},{"t":"送周汉章还吴","f":"五言律诗","c":["辕门一相见，声价重南金。","献我平蛮策，怜君为国心。","别违还锦里，崇报待纶音。","无限思乡意，题诗泪满襟。"]},{"t":"喜闻台长李公总戎赵公同奉命出师辽东心同力同功成必矣寄鄙诗预申贺臆","f":"五言律诗","c":["爱我同台长，公清果独贤。","立朝才几日，出塞屡经年。","北敌终颠覆，东人解倒悬。","征夷又豪杰，同拟上凌烟。"]},{"t":"赠南海张行人戟 其一","f":"五言律诗","c":["十载皇华使，贤名动四方。","又乘司马传，重过魏公乡。","昼锦添新彩，寒梅发古香。","荣恩须补报，莫遣岁时荒。"]},{"t":"赠南海张行人戟 其二","f":"五言律诗","c":["塞北曾相识，越南今又逢。","如何两蓬鬓，都未歇萍踪。","对酒心同感，思乡兴独浓。","无能了公事，怅别意重重。"]},{"t":"送骆司训秩满赴京","f":"五言律诗","c":["羡君司训久，遗爱入人深。","已有成材效，都无计利心。","离筵歌白雪，别泪湿青襟。","此去应遭遇，春风听好音。"]},{"t":"思亲堂为吴县主簿李京春题","f":"五言律诗","c":["椿凋萱尚茂，游子思难禁。","长望号天地，如何分古今。","不回观化梦，空负倚闾心。","惟有脩臣节，荣亲报亦深。"]},{"t":"挽骆司训乃尊易简翁","f":"五言律诗","c":["易简久即世，如何人共怜。","曾看太史传，又见令郎贤。","孝行词林颂，书香泮水传。","悬知无愧怍，含笑入重泉。"]},{"t":"题致政张起韶太守双雁图","f":"五言律诗","c":["高飞出上林，旅立在江浔。","不恋稻粱美，自怡云水深。","弋人空远慕，野鸟谩相侵。","还看腾霄去，春风听好音。"]},{"t":"舟至南浦适亲友袁州同知莫伯颙来考绩既送予至丰城书此赠别","f":"五言律诗","c":["良会不易得，联舟三日行。","喜君书上最，与我叙离情。","循吏真无忝，交亲预有荣。","明廷公论在，看尔奋鹏程。"]},{"t":"成化七年春二月十有八日余与总镇太监陈公总兵官平江伯陈公视耀武扬威关二公留款庆林寺寺前山坡之上其平如掌下临长江旁列茂树众登览为之跃然喜胜地之偶得感二公之高情而慨念时事遂及西师不觉浩然兴发因作一诗书贻寺僧同游者参议王孟育冯文纲也","f":"五言律诗","c":["严关阅初遍，下马憩禅林。","树覆连天幕，泉鸣隔涧琴。","忧民成老疾，报国喜同心。","闻道西征急，何时听捷音。"]},{"t":"谢陈总兵送毡帽","f":"五言律诗","c":["瘴乡风力恶，头骨痛难禁。","新帽劳君送，高情爱我深。","清晨笼短发，暖气温华簪。","感德惭无报，缄诗表寸忱。"]},{"t":"四月十三日西轩晚坐偶成","f":"五言律诗","c":["池亭晚来坐，对景已忘言。","月色犹未满，蛙声空自喧。","八年游岭海，何日到乡园。","西北还多事，冥思心更烦。"]},{"t":"挽南京大理何寺丞衷","f":"五言律诗","c":["详刑初拜命，观化遽伤生。","未授廷丞席，空蜚徐杜声。","金陵归旅衬，玉峡起新茔。","留得秋台绩，无惭甲第名。"]},{"t":"李节妇诗","f":"五言律诗","c":["苦节三十载，一乡人共尊。","荐书辞达上，恩典未旌门。","笋采名不死，共姜诗尚存。","相将荷褒赠，云路有贤孙。"]},{"t":"寿张同年都宪","f":"五言律诗","c":["老我同年友，相逢总异乡。","一尊初庆度，七夕喜新凉。","抚镇勋劳大，驱驰道路长。","无能遥附骥，凝睇海茫茫。"]},{"t":"题聚奎楼 其一","f":"七言律诗","c":["腰横博带气横秋，仿古抡材共倚楼。","杨子从来识词赋，魏公元薄快恩雠。","疏帘秀捲青山入，高栋光依白日浮。","闻道边尘犹未洗，欲升豪杰挽河流。"]},{"t":"题聚奎楼 其二","f":"七言律诗","c":["楼成星聚兆文明，此日登临客况清。","报国未能酬素志，兴贤深望济苍生。","云开南浦双眸豁，月照东湖一掌平。","寄语苏公好珍重，莫教方叔误时名。"]},{"t":"题尘清亭 其一","f":"七言律诗","c":["亭上花枝覆草塘，亭前流水引源长。","移来湘浦千竿雨，分得濂溪十里香。","吟到碧天明月上，醉眠白石晚风凉。","太平自有无穷乐，不为吹笙杂鼓篁。"]},{"t":"题尘清亭 其二","f":"七言律诗","c":["一尘不到草亭深，雅称秋台铁石心。","星聚衣冠占太史，风流觞咏继山阴。","柑分低树和烟摘，酒出行厨带月斟。","宾主淹留归路晚，满天风露夜沈沈。"]},{"t":"寿詹事府唐录事先生","f":"七言律诗","c":["满袖天香午退朝，华堂开宴沸云韶。","青田白鹤仙风在，绣绂苍麟瑞应昭。","事业终期齐广受，寿龄还拟等松乔。","酒酣试倚阑干望，南极文星映九霄。"]},{"t":"重庆堂为贡士顾祯题","f":"七言律诗","c":["可乐无如具庆心，君家重庆乐尤深。","报刘殊胜陈情密，事点还同养志参。","百岁奉萱培二本，一生爱日惜分阴。","高堂华扁须珍重，早晚恩光拟照临。"]},{"t":"营建纪成陈都堂命为阮太监题","f":"七言律诗","c":["内相承宣下玉阶，经营殊不费民财。","圣明仁化如天覆，黎庶欢心若子来。","洛水功成光镐邑，斯干诗咏继灵台。","有周俪美逢今日，欲献赓歌愧菲才。"]},{"t":"挽道士陈缉熙求","f":"七言律诗","c":["九转丹成生羽翰，烟霞拂袖出尘寰。","壶中演秘龙初伏，岛外寻真鹤未还。","松径净迷苍雪冷，竹窗空锁白云间。","洞庭凉夜吹箫过，水满江天月满山。"]},{"t":"长洲张医士妻葬青龙坞陈都堂命作挽诗","f":"七言律诗","c":["瑶池会看舞山香，尘满芙芙月满堂。","乌鹊桥空红雨乱，青龙坞远白云荒。","医传上国思贤助，学富东吴慕义方。","嬴得乡评重潜德，为题诗句共揄扬。"]},{"t":"挽薛亚卿父","f":"七言律诗","c":["词翰兼优绝代无，养高不受俗尘污。","忽从瑶水群仙会，遂判香山九老图。","丹凤衔书恩礼重，苍龙解绂泪痕枯。","传家幸有皋陶子，大展经纶弼圣谟。"]},{"t":"送杨练师受度牒还山陈缉熙求","f":"七言律诗","c":["早闻学道出尘寰，今喜观光觐圣颜。","黄石素书传圯上，青牛紫气度函关。","九重帝泽千年遇，万里仙槎八月还。","此去知君招不得，想应跨鹤入茅山。"]},{"t":"题吴御史昌衍所藏先世菊隐卷","f":"七言律诗","c":["三径黄花事退休，故家诗画几时留。","满笺香墨腾风露，万斛明珠缀冕旒。","流落久嗟遗泽泯，来归深喜后人求。","珍藏莫道凋零尽，尚有文光射斗牛。"]},{"t":"挽姑苏张医士","f":"七言律诗","c":["遁迹吴山世业医，家声高与古人期。","杏栽董奉空千树，鹤驾苏耽去几时。","松柏寒云愁满地，梧桐秋雨泪连枝。","百年馀庆今何在，嬴得诸郎有白眉。"]},{"t":"题顾仲礼藏春楼","f":"七言律诗","c":["香满吴山总是春，楼中春意浩无垠。","暖风入座鸟声细，晴雨捲帘花气新。","万物均含形色性，一腔同寓发生仁。","何当袖拂烟霞去，卜筑相依养道真。"]},{"t":"屏山楼胡御史拱辰为舒安求","f":"七言律诗","c":["名山相对搆层楼，山势如平翠欲流。","云捲半帘天影近，风来满座雨声浮。","羊元独卧筠床晚，苏轼重游赤壁秋。","千载芳名今并美，好传家业振箕裘。"]},{"t":"松轩为乡人题","f":"七言律诗","c":["百亩田园万树松，结轩相对日从容。","天风夜半来鸣鹤，雷雨春深起蛰龙。","香入吟窗钩翡翠，清分坐榻湿芙蓉。","几回乡梦曾相过，身在徂徕第一峰。"]},{"t":"文会堂为姑苏唐以敏题","f":"七言律诗","c":["新筑茅堂傍竹林，茅堂隐隐竹森森。","朋簪累盍薰陶久，丽泽相资造诣深。","明月半窗无俗侣，清风一曲有知音。","何时归棹吴江上，共挹沧浪洗渴心。"]},{"t":"仁化草堂为曲江黄御史父处士题","f":"七言律诗","c":["为爱茅堂近曲江，云山叠叠水淙淙。","一筇晴雨行南亩，半榻清风卧北窗。","少室山人今有几，杜陵野老古无双。","传家又得宁馨子，衣绣乘骢在帝邦。"]},{"t":"恬澹轩为大德观王道士题","f":"七言律诗","c":["昔年欲问参同契，暇日曾过恬澹轩。","羽客相逢应悟道，黄庭诵罢竟忘言。","宾墀苔老稀人迹，仙丈云深绝市諠。","身世飘然如物外，何须更懝访桃源。"]},{"t":"都门别意送陈都宪从子佶省都宪毕归吴","f":"七言律诗","c":["鸟啼花发媚皇州，袖拂东风去莫留。","客计不知归路倦，乡心应念倚闾愁。","百年门第天伦重，万卷诗书世德修。","闻道严君思仲父，看云白昼卧江头。"]},{"t":"河阳亭为吴兴潘用中题其孙景善登太学岳之裔也","f":"七言律诗","c":["潘氏园亭桃李盛，栽培先德动遐思。","好花不异河阳县，明世应非典午时。","尊俎当筵留野客，溪山入座助新诗。","贤孙早晚腾霄汉，枯槁行沾雨露滋。"]},{"t":"题沈进士纪松月扇面","f":"七言律诗","c":["谁将轻箑图松月，一握双清惬素心。","云净九霄仙兔出，风生万壑老龙吟。","庙堂大用期登进，海宇馀光仰照临。","珍重乌台挥动处，红尘相避不相侵。"]},{"t":"都门别意为曲江黄御史父作","f":"七言律诗","c":["冠盖如云出帝都，送君何处是归途。","曲江秋水鸥寻侣，丹穴朝阳凤忆雏。","双屐行探春信早，一尊吟对月明孤。","草堂到日多耆旧，重画香山九老图。"]},{"t":"送上虞罗御史澄使闽中","f":"七言律诗","c":["使者新裁豸锦衣，故乡便道喜荣归。","九重严命龙章宠，七帙慈亲鹤发稀。","堂北花香秋正好，越南山色昼生辉。","闽天后夜人瞻处，执法星光映太微。"]},{"t":"交代芮御史钊按治江西诗送还京","f":"七言律诗","c":["同年同志复同官，客里相逢握手欢。","千里归心辞我易，一年新政继君难。","鄱湖水落清秋度，庐阜峰高后夜看。","朝退金门如有暇，老亲烦为报平安。"]},{"t":"赠刘状元代祀舜帝便道故乡展焚黄礼","f":"七言律诗","c":["远将玉帛祀先皇，秋雁寒云满路香。","白发喜归梁颢第，锦衣荣过魏公乡。","书衔彩凤光松梓，梦绕飞龙在庙堂。","忧国忧民丈夫事，回轩莫待菊花黄。"]},{"t":"闻杨亚卿弟宜有御史之擢","f":"七言律诗","c":["郡博先生庆泽深，传家昆季更谁伦。","难兄久佐秋台政，阿弟新迁宪府臣。","五色云中双凤鸟，九重天上对麒麟。","匡时更有经纶事，不数三苏与二陈。"]},{"t":"送胡御史渊还京次留别韵","f":"七言律诗","c":["手持玉斧靖三边，人颂清名继四贤。","恋阙久知心捧日，封章几见力回天。","云开庐岳迎归旆，水满鄱湖送去船。","万里同来不同往，江亭绿酒兴悽然。"]},{"t":"送姑苏潘进士暄淮府造坟事竣还京","f":"七言律诗","c":["南浦西风酒一尊，乡情分袂暗销魂。","成功已副贤王意，奏绩应沾圣主恩。","家近松陵山有色，舟经杨子水无痕。","欲知后夜相思处，月满霜台独倚门。"]},{"t":"景泰改元正月一日王潘二进士赍敕奖劳亚卿杨公有清勤公正之褒且有金帛之赐诗以贺之","f":"七言律诗","c":["中兴圣主重贤劳，衮冕临轩遣俊髦。","宠遇共誇金帛赐，清勤无忝玺书褒。","九霄雨露新春被，一代君臣此日遭。","江石苍生望风采，庐山光价两相高。"]},{"t":"正统己巳秋客中闻大驾北狩未还惊号赋此","f":"七言律诗","c":["翠华北狩正侵彊，未报归期重感伤。","百辟有谁能扈跸，一身无计可勤王。","龙沙碛里秋容惨，羌笛声中夜漏长。","怅望何时遂迎复，西风吹泪洒苍苍。"]},{"t":"琴鹤轩为王仪宾题","f":"七言律诗","c":["承运朝回脱锦衣，瑶琴白鹤两忘机。","弦中一曲成连至，天外数声和靖归。","台榭月明迷素羽，琅玕风动杂金徽。","纷纷尘事浑忘却，歌舞何曾满绣帏。"]},{"t":"冰壶为前人题","f":"七言律诗","c":["幽人常在雪轩居，恍若清冰置玉壶。","昼静一尘无处著，岁寒三友隔帘呼。","间从芳沼寻鸥侣，睡起开笼放鹤雏。","闻道丹青尤绝笔，时时写拟辋川图。"]},{"t":"次韵题李主事叔玉使节还京卷","f":"七言律诗","c":["一点丹心忆翠华，无边风景送星槎。","寒云渺渺随秋雁，孤鹜翩翩带落霞。","自信穷经能致用，谁知忧国总忘家。","何当拂袖同归去，十二街头扫雪花。"]},{"t":"次李主事过惶恐滩韵","f":"七言律诗","c":["锦缆牙樯江上过，滔天烟焰起风波。","欲将一臂扶周鼎，可奈三军作楚歌。","誓死不依元日月，精忠独照宋山河。","试听惶恐滩头水，犹似当年呜咽多。"]},{"t":"景泰庚午客中中秋有感去岁此日有土木之变鸾舆未复","f":"七言律诗","c":["客里中秋忆去年，望云遥拜泪潸然。","唐人未睹朝仪复，汉将谁扶国步颠。","借问几人随幸辇，空传一雁到冰天。","凄凉最是今宵月，莫向千门万户圆。"]},{"t":"谒鄂王祠","f":"七言律诗","c":["南渡君臣社稷轻，独将大义振孤兵。","两行泪滴中原地，一点心悬五国城。","竹帛芳名今照古，庙堂遗像死犹生。","九原若遇秦奸贼，为问谁家父子荣。"]},{"t":"送朱御史骥出使淮楚","f":"七言律诗","c":["面带霜威出内台，光腾执法射三台。","观风久熟宜民政，按部今施济世才。","当道豺狼何日遁，朝阳凤鸟几时来。","知君素有澄清志，一点丹心莫暂灰。"]},{"t":"张评事柷坐累出为处州知事暨丁内艰服阙朝京赋诗留别次韵奉赠","f":"七言律诗","c":["早岁香名禁籍收，腰横博带气横秋。","平反有誉传中外，谪宦无惭任去留。","鸾凤终非鹰隼类，江湖须抱庙堂忧。","朝天此去沾恩宠，肯使潮阳困白头。"]},{"t":"鸳湖归棹为姑苏屯田张指挥作","f":"七言律诗","c":["九重宵旰重兵农，阅稼将军已建功。","万顷垂花田似锦，一帆归棹气如虹。","牙旗光射鸳湖水，鼓角声传虎帐风。","自古忠臣报明主，济川勋业是英雄。"]},{"t":"拜都御史之命留别广东诸同寅","f":"七言律诗","c":["相亲未久即相知，忍向江头话别离。","明主恩深无可报，苍生望重有何为。","舟移南海乘潮发，帆挂东风带雨吹。","明到梅关重回首，天南天北几相思。"]},{"t":"寄赠吴中诸友","f":"七言律诗","c":["皇华使者日边来，叨拜纶音总内台。","四海澄清元有志，百寮表率愧非才。","风霜敢谓摇山岳，雨露终期振草莱。","却叹君恩无可报，惟将三尺效涓埃。"]},{"t":"赠杨佥宪焕进表之京","f":"七言律诗","c":["清白声华重外台，化行雨露令风雷。","远将臣子千秋录，欲献君王万寿杯。","紫禁嵩呼欢拜舞，黄封宴锡喜追陪。","却惭无计相随去，梦绕飞龙日几回。"]},{"t":"久旱得雨忧民之怀顿释赋一诗志喜","f":"七言律诗","c":["亢阳且久田将芜，三农老稚皆号呼。","帝德广运化工妙，天瓢一洒雨泽敷。","岂但炎蒸已尽濯，坐令枯槁能还苏。","安得九州总若此，苍生有望饥寒无。"]},{"t":"寿简庵王先生","f":"七言律诗","c":["五年不预庆长生，遐想高堂喜更荣。","酒出黄封留客醉，袍裁赐锦照人明。","算齐龟鹤应无限，梦叶熊罴定有徵。","昨夜关心望南极，衣冠遥拜不胜情。"]},{"t":"挽大宗伯王文安公","f":"七言律诗","c":["四朝东阁掌丝纶，八座南宫领缙绅。","词苑文章称独步，兰亭翰墨更谁伦。","夜阑忽见星沉壁，梦里惊闻岁在辰。","一卷泉坡吾道在，里人休解绂麒麟。"]},{"t":"送洛阳严进士宪来江西劳功因便道故乡还京","f":"七言律诗","c":["口衔天语临江右，劳却功臣便问津。","画舫轻摇彭蠡曙，锦衣归看洛阳春。","从来科目贤才盛，况际朝廷治化新。","去去若承前席问，好攎忠赤献经纶。"]},{"t":"寄乡郡朱太守","f":"七言律诗","c":["一郡黎元仰福星，已魁循吏传中名。","爱民不数刘宽恕，律已还高伯起清。","莫叹长才淹白发，终期入相慰苍生。","独惭浅薄登清要，补报无能负圣明。"]},{"t":"题节亭 其一","f":"七言律诗","c":["南曹司寇旧园亭，窗户玲珑昼不扃。","新水一池金作队，繁花满障锦为屏。","非因玩物移心志，且欲偷闲养性灵。","有客相过莫相诮，古人忧乐是仪刑。"]},{"t":"题节亭 其二","f":"七言律诗","c":["为民为国日劳勤，公暇园亭暂息纷。","祗是片时能适兴，谁言一饭敢忘君。","雨荒阶藓堆苍雪，风约池萍破绿云。","安得关西夫子至，看花对酒细论文。"]},{"t":"寄内叔金上舍","f":"七言律诗","c":["牛眠冈上雨初收，著却儒衣泮水游。","头上焰光高几尺，笔端文彩焕三秋。","登科肯落王曾后，对策还轻贾谊流。","来岁乡闱文字录，先烦归雁寄洪州。"]},{"t":"巡部道上清就中一宿因登草亭次松雪翁韵二首 其一","f":"七言律诗","c":["仙子飞升在此亭，几多仙迹写丹青。","旌阳蛟斩非无术，勾漏丹成信有灵。","引凤尚传吹紫竹，笼鹅曾请写黄庭。","至今谈起成真诀，龙化人来侧耳听。"]},{"t":"巡部道上清就中一宿因登草亭次松雪翁韵二首 其二","f":"七言律诗","c":["龙虎山东一幔亭，昔人曾此礼空青。","寻真不用穷三岛，演法频烦拱百灵。","炼就丹砂出尘世，已骑黄鹤上天庭。","我来假榻清无限，万壑松风枕上听。"]},{"t":"挽胡知县以子贵封御史致政","f":"七言律诗","c":["擢第推封荷宠荣，宦途虽好倦逢迎。","归来彭泽心方逸，飞去旌阳骨已轻。","三径菊荒谁送酒，十洲云杳自吹笙。","百年遗德今何在，试听朝阳彩凤鸣。"]},{"t":"送同年卢黄门祥起复之京","f":"七言律诗","c":["十年禁闼著贤声，三载终堂尽孝情。","黪服著来痕血泪，画船乘去挂风旌。","丈夫大志图忠节，圣主中兴重老成。","莫叹前程遭遇晚，金瓯已复子龚名。"]},{"t":"倚韵奉答赵中书昂二首 其一","f":"七言律诗","c":["卓荦才华迈子云，紫薇花底散清芬。","一池墨水时相近，满案芭蕉日更勤。","金匮夜抽书总秘，玉堂昼直漏稀闻。","宦情莫叹遭逢晚，圣主于今正右文。"]},{"t":"倚韵奉答赵中书昂二首 其二","f":"七言律诗","c":["松雪仙翁非世人，玉为肌骨水为神。","挥毫每见烟生纸，题璧曾烦袖拂尘。","霄汉十年明圣宠，风云千载壮图伸。","古来书法多名世，独数公权是谏臣。"]},{"t":"寿渔乐先生七十一","f":"七言律诗","c":["绣绂苍麟在练川，狐南光彩照华颠。","天孙佳节迟三日，莱子遐龄过一年。","江上昔曾徵钓叟，山中今见有神仙。","锦袍庆罢长生会，明月清风伴醉眠。"]},{"t":"送陈汝善还姑苏","f":"七言律诗","c":["相门才子吴中彦，袖挟天风遍九围。","万里好山吟不尽，满船明月载将归。","陶潜径里香醪熟，张翰江头晚稻肥。","君去养亲吾未得，葑城空望白云飞。"]},{"t":"寿简庵王黄门先生","f":"七言律诗","c":["亲荷推封职再迁，皇都昼锦似神仙。","堂开王母蟠桃宴，人庆尧夫得子年。","松柏从来迟涧畔，芝兰终见秀庭前。","昨宵遥望燕山拜，一点狐南照九天。"]},{"t":"赠何太守盛之高州七月四日","f":"七言律诗","c":["面奉纶音下日边，高凉千里去承宣。","华风满地回枯草，霖雨随车洗瘴烟。","泉落龙湫双木屐，香凝燕寝一蒲鞭。","古来黄霸功成后，便有徵书到颖川。"]},{"t":"挽浮梁戴布政母恭人","f":"七言律诗","c":["懿德徽音世范模，忽捐荣养入蓬壶。","八旬四岁古稀有，七子廿孙今更无。","返哺空闻啼宰木，伤心不忍致生刍。","牛眠冈上埋朱翟，一道龙光夜月孤。"]},{"t":"送刘黄门华甫起复之京","f":"七言律诗","c":["读礼堂中骖服更，龙泉江上画船行。","封章曾效回天力，簪笔难忘爱日诚。","水落三秋孤月送，山横万岁五云迎。","金瓯已覆香名久，好献经纶佐太平。"]},{"t":"次韵酬乡人王畏斋","f":"七言律诗","c":["江上风高一雁来，文光烨烨照行台。","龙珠自有千金价，骥足终非百里才。","望重诗坛苏内翰，心涵秘学吕东莱。","相逢莫叹知音少，题壁曾烦袖拂埃。"]},{"t":"西江第一楼诗 其一","f":"七言律诗","c":["江上新成第一楼，楼中胜槩冠南州。","图分太极乾坤定，水接扶桑日月浮。","歌舞萧条千古叹，经纶虚薄半生忧。","登临却益君亲念，欲报深恩未肯休。"]},{"t":"西江第一楼诗 其二","f":"七言律诗","c":["江南佳丽满楼台，一度登临一快哉。","云母屏开凉雨过，水晶帘动暖风来。","弦歌广被明时化，文献多生济世才。","惟我致身霄汉上，廌袍端不惹尘埃。"]},{"t":"西江第一楼诗 其三","f":"七言律诗","c":["重屋临江此日登，风光满眼感怀增。","好山一带同今古，胜地千年几废兴。","已乏文章追吏部，且无德化继中丞。","凭高恨不生双翼，飞傍红云捧日升。"]},{"t":"西江第一楼诗 其四","f":"七言律诗","c":["山形西峙水流东，高架危楼映碧空。","双燕舞穿珠箔雨，群鸥飞散锦帆风。","朝廷有道三才顺，海宇无尘一望通。","莫倚清秋玩明月，错教人讶广寒宫。"]},{"t":"西江第一楼诗 其五","f":"七言律诗","c":["袖拂云霞览下方，地灵人杰异他乡。","剑江迹化龙光迥，铁柱功成蜃气荒。","高节千年扶世教，精忠万古正天常。","楼中怀感休长叹，为我吹箫引凤凰。"]},{"t":"西江第一楼诗 其六","f":"七言律诗","c":["层檐矗矗枕沧波，势入空青欲荡摩。","赞化却堪旋斗柄，洗兵还可挽银河。","山形薄暮双螺出，野气经春万马过。","王事关心归未得，倚阑东望白云多。"]},{"t":"西江第一楼诗 其七","f":"七言律诗","c":["杰构初成绝点氛，佳名新扁重高文。","风窗月槛凌千尺，水色山光占十分。","京口不须誇望海，吴门何用数齐云。","太平无事群生乐，得遂清游感圣君。"]},{"t":"西江第一楼诗 其八","f":"七言律诗","c":["缥缈江楼十二阑，常无溽暑有清寒。","閒来独伴水云坐，长啸一声天地宽。","庐岳烟开明返照，宫亭风静息狂澜。","非才却系苍生望，且莫留连尽日欢。"]},{"t":"西江第一楼诗 其九","f":"七言律诗","c":["独倚层楼玩物华，十三侯郡信无加。","海天空阔吟怀壮，吴楚微茫望眼赊。","下饮双虹垂远浦，高飞百雉起平沙。","频来莫道荒游乐，一点丹心在帝家。"]},{"t":"西江第一楼诗 其十","f":"七言律诗","c":["飞楼雄冠大江西，公暇娱情此一跻。","随水落花红滚滚，连天芳草碧萋萋。","光生旸谷三山近，气散炎荒五岭低。","兴发诗成豪未尽，更挥铁柱倚云题。"]},{"t":"题徐高士祠诗 其一","f":"七言律诗","c":["一束生刍吊古人，荒凉陈迹竟谁伦。","南州堂上空悬榻，北岳山中总滥巾。","传列逸民风世教，坊题高士式儒绅。","夜来间向东湖望，几许清光接富春。"]},{"t":"题徐高士祠诗 其二","f":"七言律诗","c":["青云梦里谢夔皋，懒受玄纁制锦袍。","贫贱不荒三径业，轻肥应薄五陵豪。","江湖寂寞流风远，光岳晶荧间气高。","过客纷纷吊遗迹，谁轻名利等鸿毛。"]},{"t":"题徐高士祠诗 其三","f":"七言律诗","c":["市隐何曾去买山，草堂元在水云间。","绝怜巢父能相让，翻笑林宗不自閒。","泰华高名藏玉检，斗牛精气接银湾。","我来吊古裴回久，带得清风满袖还。"]},{"t":"题徐高士祠诗 其四","f":"七言律诗","c":["思贤亭上咏缁衣，云满江天隐少微。","济世有心非矫俗，伤时无道却知几。","碧潭长夜苍龙卧，丹穴何年彩凤飞。","千古地灵人杰颂，西山南浦也光辉。"]},{"t":"次韵寄乡人陆务轩","f":"七言律诗","c":["不随令尹赋归来，独向烟波筑钓台。","乔木故家推世德，明珠沧海叹遗才。","鲈鱼正美陪张翰，綵服初成学老莱。","却愧宦途空窃禄，未能甘雨洗黄埃。"]},{"t":"次韵寄乡人严友兰","f":"七言律诗","c":["不羡侯门势绝伦，草堂住近绿杨津。","气充牛斗三千丈，身卧烟霞五十春。","酒肆风流豪李白，诗坛光价美苏卿。","却惭浅薄浑无补，空有丹心恋紫宸。"]},{"t":"赠致政李少卿","f":"七言律诗","c":["□□才华李杜同，人誇诗酒有遗风。","碧山修竹□□□，东阁官梅兴未穷。","花下徘徊邀皓月，篱□□□对邻翁。","相逢谩写耆英会，四海苍王仰□□。"]},{"t":"挽丰城静庵杨先生","f":"七言律诗","c":["栽成桃李满门墙，师道儒名继紫阳。","黉舍总思瞻北斗，绛帷独梦讲东堂。","剑江光燄愁将敛，学海波澜苦不扬。","愧我感恩空抆泪，无缘负土服心丧。"]},{"t":"挽乐佥宪父受封宪幕","f":"七言律诗","c":["高洁无心钓万钟，烟霞深处寄行踪。","义方成效门初表，家学能传诰已封。","霜重墨池凋碧草，云昏笔冢翳苍松。","穹碑树德当周道，多少行人为改容。"]},{"t":"和酬杨司寇","f":"七言律诗","c":["愁来无事忽登楼，独倚阑干瞻帝州。","宫阙岧峣王气合，海天空阔行云收。","故人有道掌邦禁，愧我无能空宦游。","允矣大音振治世，词林孰敢鸣相酬。"]},{"t":"赠陈佥宪濂进表之京","f":"七言律诗","c":["南薰江上浪花飞，使者扬帆向帝畿。","长剑倚云横壮气，行囊载月露清辉。","封人仰圣虔三祝，游子宁亲喜一归。","忠孝同心不同迹，海天凝望欲沾衣。"]},{"t":"送刘主事昌奉使还京便道归故乡","f":"七言律诗","c":["高第虽登不燕安，写骚亭上日忘餐。","文章渐入欧苏室，风雅将登李杜坛。","庐岳云开瞻秀爽，吴江月满照清寒。","思家无计相从去，东望空劳一永叹。"]},{"t":"四月望日驻节分宜晚眺有感","f":"七言律诗","c":["山县萧条近水坳，民风淳朴静呼詨。","荒村日落笛初歇，古寺月来钟乱敲。","聚草群哇喧鼓吹，栖林双鹊竞枝巢。","不堪便起怀归念，顿尔欲将名利抛。"]},{"t":"庆阳司寇八月十六日得子","f":"七言律诗","c":["中秋华月始流辉，便毓明珠产绣帷。","共喜仁人还有后，谁云天道竟无知。","闻啼已识真英物，作颂惭非绝妙辞。","仙种从来好花发，天香吹到凤凰池。"]},{"t":"庆张维学擢乡郡阴阳正术","f":"七言律诗","c":["家世儒医四海闻，兼通造化独超群。","公心荐剡资贤守，清职居乡感圣君。","步出杏林观地理，坐依橘井玩天文。","惠庵庆泽传来久，济美行看振二勋。"]},{"t":"庆陆务轩纳谷冠带","f":"七言律诗","c":["凶年输谷匪求恩，为济饥荒报至尊。","国典却须旌大义，宠章自是及高门。","峨冠博带乡闾羡，伟迹丰功竹帛存。","从此光前还裕后，清风千古动乾坤。"]},{"t":"挽鄱阳王府丞父","f":"七言律诗","c":["泗水行歌久断音，传经有子戴朝簪。","共誇身后推恩重，应报生前积庆深。","就养不回千古梦，流芳却慰九原心。","穹碑树德当周道，太史文章耀古今。"]},{"t":"挽鄱阳王府丞母","f":"七言律诗","c":["霜居教子已登庸，节义何惭举世宗。","大史传书青汗简，君王诰赐紫泥封。","无端婺女天边坠，有约良人地下逢。","昨向凤冈冈上吊，堂空惟有一孤松。"]},{"t":"赠渔隐李先生","f":"七言律诗","c":["白发苍颜享寿龄，幅巾黎杖适吟情。","价高未起蒲轮聘，望重频魁月旦评。","西涧松筠同晚节，北山猿鹤结深盟。","自惭薄宦浑无补，何日相从共濯缨。"]},{"t":"荣寿堂为昆山项御史璁题","f":"七言律诗","c":["碧玉峰前荣寿堂，高年慈母被恩光。","霞文帔映童颜润，珠翟冠笼鹤发长。","天禄分来春酿酒，锦衣归去昼称觞。","应知罔极真难报，孝道相期更显扬。"]},{"t":"送昆山赵进士博还京","f":"七言律诗","c":["画舫南游始盍簪，锦衣东望又分襟。","一天风月供清操，满目江山伴醉吟。","归路不辜题柱志，到家应慰倚闾心。","吾乡自古多豪杰，接武相期振好音。"]},{"t":"左都御史萧公以诗见寄依韵奉酬二首 其一","f":"七言律诗","c":["清才落落世称稀，传得声华海内思。","平法独持因爱物，谠言频进为忧时。","霜飞北阙趋朝早，日昃中台退食迟。","闻道天恩今益眷，应知心与古人期。"]},{"t":"左都御史萧公以诗见寄依韵奉酬二首 其二","f":"七言律诗","c":["西江江上雁声稀，为感交情到处思。","满路风尘行部日，一天星月倚阑时。","君恩欲拜归心急，王事图成去计迟。","终拟秋高遂深愿，相从待漏话襟期。"]},{"t":"送姚子大佥宪致仕回","f":"七言律诗","c":["早登丈席晚登台，流得芳声遍九垓。","化雨春风胡瑗教，秋霜烈日马周才。","数茎白发老将至，三径黄花归去来。","却恐蒲轮还有召，爱葵心志莫先灰。"]},{"t":"挽永新左御史父","f":"七言律诗","c":["奔走功名性不堪，远将踪迹寄烟岚。","诗朋才散苦吟歇，仙侣忽招清梦酣。","十载义方真有效，一生德望信无惭。","流芳最羡追封事，遗向禾川作美谈。"]},{"t":"挽永新左御史母","f":"七言律诗","c":["不饰金钿与凤钗，自甘勤苦作生涯。","孟光配德年相若，柳母收功愿已谐。","禾水风飘花乱落，枫塘烟锁玉深埋。","徽名有赠加身后，万古千秋第一侪。"]},{"t":"挽钱塘郑佥都父师善翁","f":"七言律诗","c":["白发朱衣耀宠光，化工独报行非常。","善从伊水天民训，义本燕山窦氏方。","云外忽传黄鹤去，江头空见白鸥翔。","于今泉夜真含笑，有子才高总宪纲。"]},{"t":"忠武堂为苏卫张指挥题","f":"七言律诗","c":["留侯世业在平江，忠武名堂世莫双。","效力已膺三圣宠，宣威曾受万人降。","葵心向暖瞻天阙，剑气生寒镇海邦。","我欲题诗扬盛烈，却惭未有笔如杠。"]},{"t":"环翠轩苏卫张指挥别墅作轩环植万柳故名","f":"七言律诗","c":["最爱将军别墅间，一轩万柳翠相环。","风翻密叶惊春浪，烟锁重阴讶晓山。","赏节弯弓曾独射，赠人分袂亦同攀。","登高若见闲松竹，还为移栽虎豹关。"]},{"t":"寄镇守宣府李执中佥都","f":"七言律诗","c":["彭城分手六年馀，远道何由问起居。","夜月空流千里梦，秋鸿閒寄数行书。","安边勋业今无忝，盖世声华古不如。","圣主忧民望康济，好宣仁化遍寰区。"]},{"t":"送黄给事中晖使满刺加国","f":"七言律诗","c":["圣主当天恤远人，分封有诏选能臣。","锦衣荣动江南昼，玉节光摇海外春。","定使百蛮皆感化，从今重译尽来宾。","古来豪杰多名世，接武相期继后尘。"]},{"t":"送同年朱佥宪骥之广西","f":"七言律诗","c":["青年雅望冠中台，荷宠归宁亦快哉。","亲舍暂分游子去，蛮邦久迓使君来。","林深丹桂行双节，野近苍梧奠一杯。","道路逢人莫长叹，庙堂方拣栋梁才。"]},{"t":"送同年杨主事益苏松蹈勘旱灾事竣还京意有所讽","f":"七言律诗","c":["传得纶音自帝都，东南凋瘵顿然苏。","忧勤已辩崔峣树，忠节还陈郑侠图。","满路欢声喧鼓吹，逼人清气湛冰壶。","回辕莫向关河滞，延伫方期赞大谟。"]},{"t":"题寿星庆琴川松溪陈宗盛乃尊竹轩翁","f":"七言律诗","c":["小春望日启华筵，初度逢君寿福全。","花甲数周才过一，椿龄算永定逾千。","雨滋轩竹枝方盛，霜老溪松节愈坚。","昨夜行台悬北望，狐南星彩照琴川。"]},{"t":"辛卯午日小宴追忆先朝苏颋人日应制韵录似游击从事诸君","f":"七言律诗","c":["午节随銮曾几回，六龙亲御五华台。","惊看羽骑绯衣度，细睹天颜宝扇开。","朝退声移苍玉佩，步归心醉紫霞杯。","金舆一去无消息，此日重逢百感来。"]},{"t":"正月十九日寄弋阳李少卿三首 其一","f":"七言律诗","c":["远道輶车日日牵，羡君踪迹似神仙。","白云万顷陪深隐，红日三竿任晏眠。","绕座埙篪声迭和，满堂绣綵业相传。","菲才亦有山林志，未报君恩空怅然。"]},{"t":"正月十九日寄弋阳李少卿三首 其二","f":"七言律诗","c":["功成不被利名牵，人慕高风迈谪仙。","松径昼开教鹤舞，桑林春老看蚕眠。","一生勋业三朝录，千古文章四海传。","愧我同心不同迹，弋山东望思悠然。"]},{"t":"正月十九日寄弋阳李少卿三首 其三","f":"七言律诗","c":["情绪游丝袅袅牵，错教人望似登仙。","关山道远何时歇，风雨衾寒到处眠。","乡梦却嫌鸡唤醒，客愁偏厌漏声传。","知君此夜浑无此，高拥青绫足宴然。"]},{"t":"赠李少卿兄渔隐先生二首 其一","f":"七言律诗","c":["高卧烟霞一布衣，平生踪迹似君稀。","邑门无事不曾到，乡社有情常醉归。","荷斧斫来林笋嫩，引泉灌得药苗肥。","山中修养年年好，焉得相从便息机。"]},{"t":"赠李少卿兄渔隐先生二首 其二","f":"七言律诗","c":["松花为食草为衣，养道延年过古稀。","留客必须春色去，登山常伴月明归。","偏怜野水群鸥好，不羡侯门驷马肥。","更喜追陪有难弟，晚年投老最知机。"]},{"t":"同李少卿游龟峰寺次其韵二首 其一","f":"七言律诗","c":["系却兰舟弋水滨，乱云堆里访山门。","年深古柏多仍在，春后残梅半不存。","燕尾溪流斜断岸，羊肠路绕曲通村。","徘徊更爱群峰好，一洗平生两目昏。"]},{"t":"同李少卿游龟峰寺次其韵二首 其二","f":"七言律诗","c":["洞天深处远江滨，路入烟霞是洞门。","环座好峰千状出，满潭清溜四时存。","曾磨厓石疑元结，欲咏梅花愧后村。","搔首何堪自东望，亲闱久矣旷晨昏。"]},{"t":"送杨宪副宜之广东","f":"七言律诗","c":["持节南巡久擅名，拜官重去副群情。","五羊城下新恩至，驷马车前故吏迎。","青草瘴消风渐转，黄梅雨歇日初明。","台端见我同寅旧，为道相思远寄声。"]},{"t":"送松江黄郎中琮广西审刑竣事还京","f":"七言律诗","c":["持节平反遵圣谟，远人处处动欢呼。","波吞瘴海穷鳞起，风转炎荒腐草苏。","归路总誇空薏苡，过乡莫待饱莼鲈。","好思南顾忧民切，早献当年郑侠图。"]},{"t":"送王府丞弼起服之京","f":"七言律诗","c":["垄树啼残谢豹声，麻衣人换锦衣行。","连天水上春帆度，捧日云边晓佩鸣。","京郡齐民怀父母，庙廊虚位选公卿。","知君此去应遭遇，好罄丹心佐太平。"]},{"t":"西轩诗为泰和萧孟廉题少师孟勤先生兄也","f":"七言律诗","c":["筑得高轩配颖滨，轩中人物异常伦。","一生义气甘韦布，四海清风动缙绅。","柱倚残阳吟到景，帘钩新月醉芳辰。","武山遥背还多趣，太史文章已具陈。"]},{"t":"题松泉图寿大司寇杨公","f":"七言律诗","c":["涧畔孤松涧下泉，清流高节自年年。","飞空作雨流偏急，向晚凌霜节愈坚。","一派源源方赴海，千寻郁郁定参天。","苍生膏泽明堂栋，都望君家祝寿筵。"]},{"t":"题松鹤寿渔乐陈先生","f":"七言律诗","c":["鸡群独立昂藏鹤，涧畔孤撑偃蹇松。","声动九皋风露夜，节凌三径雪霜冬。","顶深丹后色应变，脂化苓时阴更浓。","长岁云林有馀庆，桑轩还进大夫封。"]},{"t":"送陈御史述审刑事竣还京","f":"七言律诗","c":["南浦楼前鼓角鸣，朝天人着绣衣行。","晴波浩荡鱼龙舞，迟日光华草木荣。","一载平反无愧色，千年遗爱有贤声。","同乡未得同归去，目送征帆过葑城。"]},{"t":"裕轩为乡人徐文辉题","f":"七言律诗","c":["最爱高轩境界幽，轩中人物异常流。","丰标秀倚灵岩晓，雅量宏吞震泽秋。","万顷烟霞吟不尽，四时风月醉还留。","何当拂袖归山去，过此陪君日唱酬。"]},{"t":"午日寄杨司寇诗","f":"七言律诗","c":["陪观竞渡倚高楼，冉冉流光又六秋。","为客到今空自感，何人来此可同游。","蒲觞满引终难醉，萧鼓喧闻未破愁。","聊写新诗寄知己，江东云树重回头。"]},{"t":"宁波周御史父母双挽","f":"七言律诗","c":["士行无亏女德充，笃生佳器见登庸。","人誇偕老同观化，帝念齐贤并锡封。","七尺冢棺埋对玉，一抔新土种双松。","幽光更有铭文发，长夜神游总笑容。"]},{"t":"宿东山寺和九川李少卿韵","f":"七言律诗","c":["山可闲登水可临，禅家胜景动长吟。","水花初摘香移沼，山木渐除风满林。","海内有人愁盛暑，云中无路散清阴。","相逢最感频相勉，报国终期罄赤心。"]},{"t":"景泰丙子六月十七日便道与大理少卿弋阳李公游上清明日游仙岩皆赋七言近体诗一章书之翛然亭 其一","f":"七言律诗","c":["九载名山五度过，山容霭霭势峨峨。","洞穿海外飞仙岛，水接天中织女河。","白鹤盘风秋气近，紫箫吹月夜凉多。","宦情也动幽栖念，可奈深恩未报何。"]},{"t":"景泰丙子六月十七日便道与大理少卿弋阳李公游上清明日游仙岩皆赋七言近体诗一章书之翛然亭 其二","f":"七言律诗","c":["扁舟览胜故人同，胜境分明似画中。","阴洞满厓无路到，晴岩一窍与天通。","留传剩见神仙迹，开辟冥思造化功。","我有乡山归未得，不堪回首白云东。"]},{"t":"重游临川疏山寺次旧韵留题","f":"七言律诗","c":["一点丹心万斛愁，登山消遣记重游。","满怀冰雪空三伏，屈指光阴近八秋。","海内未瞻云气合，天中渐见火星流。","清风凉雨苏炎旱，我为苍生叩蓐收。"]},{"t":"送南城贡士左赞再赴春闱","f":"七言律诗","c":["笔阵词锋六馆推，南宫两战未登魁。","何蕃再省名逾重，维翰重升志不灰。","飞鹢秋分滕阁雨，化龙春听禹门雷。","太平桥上乡人众，望尔高车驷马回。"]},{"t":"寄乡友徐文辉","f":"七言律诗","c":["家林幽僻远尘阛，世事浮沉总不关。","下榻有时延上客，东楼终日望西山。","醉乡风月情偏好，静里乾坤意自閒。","独我相思未相见，海天云树锁愁颜。"]},{"t":"延常山杨医师炙火诗以酬之","f":"七言律诗","c":["浙水西头积庆堂，堂中人物异寻常。","轩岐妙术传三世，泰华高名动四方。","丹火暖时薰艾剂，橘泉清处淬针芒。","相逢莫厌频频疗，海内苍生多病伤。"]},{"t":"张式之佥都致政既归四明以诗寄予依韵奉酬","f":"七言律诗","c":["社稷功成归鉴湖，卧龙踪迹孰能屠。","自怜投老入佳境，应笑时人行畏途。","鸣世有声惊墨客，平蛮无愧忆征夫。","烦君谩赴耆英会，恐有徵书出帝都。"]},{"t":"挽宁波王司空母张夫人","f":"七言律诗","c":["高寿荣恩享北堂，平生德善总非常。","花封遗爱思贤助，柏府传声颂义方。","瑶水夜深仙乐动，家园春静板舆荒。","牛眠冈上新埋玉，多少行人起赞扬。"]},{"t":"寄嘉兴延太守同年","f":"七言律诗","c":["共羡嘉兴太守贤，清风善政路人传。","连城白璧无瑕玷，合郡苍生解倒悬。","西浙分襟惊数载，南州回首忆同年。","烦君此去尤珍重，莫让龚黄美自专。"]},{"t":"题湖口上钟岩寺","f":"七言律诗","c":["上方风景最清幽，驻却双旌试一游。","绝壁有岩皆起阁，归僧无路只乘舟。","天垂庐岳擎孤柱，湖落湘江界合流。","翘首不堪东北望，思乡又感庙堂忧。"]},{"t":"送李咸章贤良奉使还京 其一","f":"七言律诗","c":["相门有客清如玉，圣世徵贤喜得人。","岭海一麾宣宠命，乡园五彩慰慈亲。","星河夜静仙槎稳，江月秋高素练新。","去去青春莫虚负，丈夫功业在经纶。"]},{"t":"送李咸章贤良奉使还京 其二","f":"七言律诗","c":["白云飞送上青云，仙子才华信不群。","双璧已生烟自润，九苞初振锦成文。","从来豪杰多名世，此去勋劳在致君。","廊庙忧民如见问，博施无计愧忠勤。"]},{"t":"同弋阳李少卿宿莲塘寺次古诗韵 其一","f":"七言律诗","c":["小小禅房似画船，连床风雨拥寒毡。","几年受任惭无补，千里论交幸有缘。","松径云深迷晚鹤，槐庭霜重断秋蝉。","留题最羡文章伯，嬴得芳名后世传。"]},{"t":"同弋阳李少卿宿莲塘寺次古诗韵 其二","f":"七言律诗","c":["山寺岧峣倚碧峰，偶来假榻快心胸。","行营漏起三吹角，古殿香然一扣钟。","故旧情深欢会合，圣明恩重幸遭逢。","素餐却念农家苦，烟火东林尚夕舂。"]},{"t":"寿詹事府唐录事先生","f":"七言律诗","c":["经纬文章海内传，才名不数两疏贤。","青宫初喜承三接，紫诰行看拜九迁。","墨色帐前罗士子，蟠桃花底醉神仙。","佳辰不预长生会，山斗遥瞻祝寿筵。"]},{"t":"送佥都御史余公奉使还京 其一","f":"七言律诗","c":["久司风纪位都堂，近拜天恩使故乡。","玉斧飞霜无玷缺，锦衣行昼有辉光。","思家梦叶才温席，恋阙情悬又促装。","奈我同心不同迹，五云翘首思茫茫。"]},{"t":"送佥都御史余公奉使还京 其二","f":"七言律诗","c":["夜雨西窗始盍簪，春风南浦又分襟。","论交久契芝兰味，图报相期铁石心。","桃浪一江行色壮，锦云千里故情深。","君才自是人中杰，入相行看拜玉音。"]},{"t":"送佥都御史余公奉使还京 其三","f":"七言律诗","c":["水满春江燕子飞，喧天鼓吹送君归。","许身报国今谁并，持节还乡古亦稀。","龙虎风云欣际会，山光草木剩光辉。","相思后夜瞻霄汉，执法星芒耀太微。"]},{"t":"送佥都御史余公奉使还京 其四","f":"七言律诗","c":["酒罢西江第一楼，还朝人物异常流。","作官最重乡邦羡，奉使能分社稷忧。","此去横班须独对，遥知前席定三留。","好将民隐条陈尽，为报皇情宠眷优。"]},{"t":"寿徐裕轩诗","f":"七言律诗","c":["玉雪风姿照美髯，太平初度乐无边。","天开令节才三日，人祝遐龄又一年。","自古中原有麟凤，于今平地见神仙。","知君已得长生术，岁岁歌诗庆寿筵。"]},{"t":"送胡共之参政赴广东","f":"七言律诗","c":["江头樽酒话襟期，君欲南征我北驰。","十载交游恒间阔，一时相见又分离。","海天绿树春云望，台阁清灯夜雨思。","此后重逢问何日，鹍鹏应不久藩篱。"]},{"t":"清明谒三陵道宿僧寺次姚亚卿韵二首 其一","f":"七言律诗","c":["东行联辔扣禅关，楼阁孤撑返照间。","抚景渐看三月近，寻芳聊趁一时閒。","风翻冻柳莺声怯，云薄空山雨意悭。","何事匆匆不遑乐，九重咫尺是天颜。"]},{"t":"清明谒三陵道宿僧寺次姚亚卿韵二首 其二","f":"七言律诗","c":["多年荒寺枕山肩，人厌萧条我独怜。","市语不喧春鸟哢，梵音初动晚香然。","数杯浊酒催诗饮，一榻清风伴月眠。","翘首不堪心事切，红云高处白云边。"]},{"t":"挽刘司寇广衡","f":"七言律诗","c":["高步云霄近上台，司刑司宪展多才。","调元未副苍生望，观化何堪白发催。","双履无声趋晓禁，五花有迹在秋台。","东风执绋都门道，目断天南不尽哀。"]},{"t":"赠璇上人南归","f":"七言律诗","c":["脱却尘凡守寂寥，远公门下特高标。","锡飞已占吴山胜，杯度何妨楚水遥。","南垄蘋蘩春自荐，北堂甘旨昼亲调。","怜君独遂还乡愿，梦绕江天恨未消。"]},{"t":"送叶佥都与中巡抚两广","f":"七言律诗","c":["东山强起副皇情，荣拜都堂暂远行。","重寄一麾兼两镇，先声万里慰群生。","风恬沧海鲸波净，雨洗黄尘鸟道清。","自古安边重韩范，终归黄阁佐承平。"]},{"t":"挽刘詹事宗器","f":"七言律诗","c":["词林璧水久蜚英，晚辅春宫重老成。","操履一生行古道，文章千载占时名。","调元未见登黄阁，观化俄闻上玉京。","惆怅东风招不起，懒挥铁笔写乡评。"]},{"t":"松轩为陈詹事安简乃弟题","f":"七言律诗","c":["双树亭亭荫荜门，隐君难与世人论。","七松处士遗风在，五柳先生旧业存。","洗耳静闻清籁响，科头坐爱碧云屯。","休徵已叶难兄梦，位接三台拜宠恩。"]},{"t":"送张进士养病回苏州","f":"七言律诗","c":["琼林深处正翱翔，忽拜殊恩望故乡。","桃叶波平归棹稳，柳花风细赐衣香。","参苓调养回元气，甘旨欢娱慰断肠。","独我分携重惆怅，海天翘首白云翔。"]},{"t":"高邮吴司训升原武教谕乡人也诗以送之","f":"七言律诗","c":["手栽桃李满盂城，献绩金门荷宠荣。","百里儒官司教化，一方人物赖陶成。","研朱点易芹香暖，捲幔观澜雨气清。","此去休言官独冷，显扬还儗振家声。"]},{"t":"挽佥都御史左周器","f":"七言律诗","c":["为民为国一生心，晚进中台感激深。","明主有恩方倚重，怜君无命忽销沉。","斗山光价流中外，墓道铭章耀古今。","我有深情招不起，禾川南望引长吟。"]},{"t":"挽国子邹检讨","f":"七言律诗","c":["栽成桃李满皇都，懒逐风尘走宦途。","林下一人方入会，山中九老不成图。","鸟呼笔冢云烟起，□□诗坛草木枯。","欲问流芳在何处，高冈真有凤凰雏。"]},{"t":"庆左进士赞擢稽勋主事","f":"七言律诗","c":["羲献书名屈宋文，春雷声里上青云。","天官分职非常选，圣主抡才喜出群。","鸣佩晓听双阙漏，挥毫时叙百僚勋。","烦君莫负平生志，留取芳名后世闻。"]},{"t":"寄乡友沈文用","f":"七言律诗","c":["沈家林馆最清幽，曾伴相知载酒游。","宦迹北驰才隔岁，乡心南望几经秋。","芳春桃李开花未，深夜壶觞醉客不。","羁绊无能寻旧约，题诗聊为主人酬。"]},{"t":"寄乡友陈宗盛","f":"七言律诗","c":["客况乡情正不禁，远劳一价送佳音。","开缄快睹龙蛇字，念旧深知铁石心。","万里海天春渺渺，半窗风雨夜沉沉。","相思苦被浮名绊，尊酒何时更盍簪。"]},{"t":"奉送尊师唐先生判金华","f":"七言律诗","c":["驿亭清酒汎黄花，旧馆诸生满路遮。","亲炙久期联玉笋，分违遥送判金华。","从来儒术堪经世，此去乡心莫恋家。","早使提封遂康济，趋朝终儗拜黄麻。"]},{"t":"挽徐给事中父太学生","f":"七言律诗","c":["花落梅窗香不闻，中年观化出尘氛。","眉山苏老能传业，太学何蕃未策勋。","玉洞露寒閒点易，琼楼月满静修文。","流芳却有推封诏，夜夜龙光照古坟。"]},{"t":"庆陈梅轩封御史","f":"七言律诗","c":["鸾书飞舞下天阍，光射东吴孝义门。","七品一官封子职，十年两世拜皇恩。","湖山草木增新彩，乡里衣冠庆达尊。","我有深情不能预，海天空望白云屯。"]},{"t":"具庆堂为程员外宗题","f":"七言律诗","c":["秋台绩奏称才良，宠命新颁具庆堂。","数朵彩云将雨露，两簪苍雪耐风霜。","光摇金翠瞻天近，景驻桑榆爱日长。","移孝为忠丈夫事，好摅忠荩答君王。"]},{"t":"寄题何挥使西轩","f":"七言律诗","c":["最爱西轩称此心，分明城市有山林。","石潭倒浸芙蓉朵，竹径斜穿玳瑁簪。","尘印荒苔人迹少，歌传丛树鸟声深。","宦游未得陪佳赏，翘首江天想像吟。"]},{"t":"重庆堂为御史郑时题时伯父为秋官亚卿父与大父皆受封","f":"七言律诗","c":["世父登朝犹子继，推封共喜拜恩频。","几函诰敕来双凤，三代簪缨见四人。","桥梓清阴高覆下，芝兰香气旧和新。","光荣今古谁能及，图报应须作荩臣。"]}]};